window.__LITE_PARTS__=window.__LITE_PARTS__||[];window.__LITE_PARTS__.push([{"t":"极性纤锌矿 NbAlN：一种用于极化工程 GaN 异质结构的过渡金属氮化物合金","b":"ABSTRACT The discovery of ferroelectric ScAlN sparked a search for new polar wurtzite alloys; however, incorporating transition metals remains a formidable challenge. Here, we demonstrate the synthesis of wurtzite‐phase NbAlN, a polar transition‐metal nitride alloy that is highly compatible with GaN‐based heterostructures. Despite the strong metallic character of elemental Nb, we achieved coherent epitaxial NbAlN films that preserve the wurtzite crystal structure and metal polarity of the underlying GaN, as directly visualized by annular bright‐field scanning transmission electron microscopy. Nb incorporation induces a monotonic lattice expansion and produces coherent Nb‐enriched nanoscale regions that are accommodated within the continuous wurtzite framework. Functionally, NbAlN barriers induce a substantial enhancement in the two‐dimensional electron gas density at the AlN/GaN heterointerface, consistent with polarization‐related carrier modulation by the metal‐polar NbAlN barrier. This study demonstrates that d ‐electron transition metals can be integrated into polar nitride systems without compromising their functional asymmetry, making NbAlN a promising building block for polar nitride heterostructures and carrier‐density‐engineered GaN electronics.","d":"2026-09-03","u":"https://advanced.onlinelibrary.wiley.com/doi/10.1002/adma.74756","c":"AI与智能科技/AI硬件层/半导体","a":"Advanced Materials","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"氮化物合金","sc":7.2,"scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"aip":1,"as":"研究人员成功合成纤锌矿相NbAlN极性过渡金属氮化物合金，与GaN基异质结构高度兼容。尽管单质Nb具有强金属性，仍实现了保持底层GaN纤锌矿晶体结构和金属极性的共格外延NbAlN薄膜，并通过环形明场扫描透镜电镜直接观察证实。Nb掺入引起单调晶格膨胀，并形成连续纤锌矿骨架内相容的Nb富集纳米区域。功能上，NbAlN可作为极化工程GaN异质结构的势垒层。","kp":["材料[极性纤锌矿过渡金属氮化物合金]: NbAlN","制备质量[NbAlN薄膜]: 与GaN基异质结构高度兼容的共格外延生长，保持纤锌矿晶体结构与金属极性"]},{"t":"通过精确的静电钉扎和梯度屏蔽打破富锂层状氧化物阴极中的降解多米诺骨牌","b":"ABSTRACT Benefiting from the anionic redox activity, lithium‐rich layered oxide cathodes exhibit high specific capacity, but the migration of transition metal (TM) can exacerbate vacancy clustering, resulting in domino‐like structural degradation. To stabilize the structure, the electrostatic pinning effect is precisely incorporated into the Li layer to mitigate the TM migration via strong electrostatic repulsion. Concurrently, this configuration effectively modulates the electronic distribution around the oxygen ligands, thereby stabilizing the oxygen redox. Furthermore, robust electrostatic interactions endow the material with the capability to adaptively adjust its interlayer spacing, thereby buffering the structural evolution of the layered framework during (de)lithiation processes. The modified cathode achieves an 89.1% capacity retention over 400 cycles in half‐cells and an impressive 96.2% over 1000 cycles in full cells. To further decouple the capacity‐stability trade‐off while concurrently enhancing both bulk and interfacial stability, we engineered a gradient shielding architecture. This design not only attains 219.8 mAh g −1 at 0.5C and delivers capacity retention of 90.8% after 400 cycles but also promotes the formation of a compact CEI at the near‐surface region, markedly improving interfacial stability under harsh conditions. This progressive structural engineering paradigm offers fresh insights into overcoming the intrinsic structural challenges of lithium‐rich cathode materials.","d":"2026-09-03","u":"https://advanced.onlinelibrary.wiley.com/doi/10.1002/aenm.71518","c":"零碳产业/能量循环/能量存储/电化学储能/二次电池/锂电池","a":"Advanced Energy Materials","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"富锂阴极","sc":6.6,"scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.5,"t":5.0},"aip":1,"as":"富锂层状氧化物正极虽因阴离子氧化还原活性具有高比容量，但过渡金属迁移加剧空位聚集，引发多米诺式结构退化。该研究将静电钉扎效应精确引入锂层，通过强静电排斥缓解过渡金属迁移，同时调控氧配体周围的电子分布以稳定氧氧化还原。此外，强静电相互作用赋予材料自适应调整层间距的能力，缓冲（脱）锂过程中层状框架的结构演变，从而打破结构降解的连锁反应。","kp":["稳定化策略[富锂层状氧化物阴极]: 精确静电钉扎引入Li层抑制过渡金属迁移，并调制电子分布以阻断空位聚集引发的多米诺式结构降解"]},{"t":"表面应变 NiMo 阴极可实现动力学解耦氢气泡管理，实现稳定的近中性水电解","b":"ABSTRACT Gas evolution during water electrolysis forms bubble layers that block active sites and increase transport and ohmic losses. Decoupling bubble‐mediated mass transport from intrinsic hydrogen evolution reaction (HER) kinetics remains challenging because surface modifications affect both activity and bubble dynamics. Here, a surface‐strained NiMo cathode ( s ‐NiMo) enables kinetics‐decoupled hydrogen bubble management in a near‐neutral electrolyte. In 0.5 m potassium phosphate buffer (pH 7.0), NiMo and s ‐NiMo exhibit nearly identical intrinsic HER kinetics, consistent with similar H* adsorption energetics. Under bubble‐regulated operation, s ‐NiMo shows a 63 mV lower steady‐state overpotential at −20 mA cm −2 . High‐speed imaging reveals smaller, faster‐departing H 2 bubbles, reducing the mean residence time from 0.5 s to 0.2 s. Interfacial analyses indicate enhanced hydrophilicity and more negative surface‐charge‐related characteristics. Ensemble calculations based on the Universal Model for Atoms show that the surface‐associated *H 2 state is 0.52 eV higher in the s ‐NiMo‐representative environment, while electrochemical fluorescence lifetime imaging microscopy reveals a 1.5‐fold higher nanobubble event density. In a single‐cell electrolyzer at 300 mA cm −2 , s‐NiMo maintains a 280 mV lower cell voltage over 100 h. These findings establish bubble management as an independent design axis for stable near‐neutral water electrolysis.","d":"2026-09-03","u":"https://advanced.onlinelibrary.wiley.com/doi/10.1002/aenm.71545","c":"零碳产业/能量循环/能量存储/化学能/氢基能源","a":"Advanced Energy Materials","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"水电解制氢","sc":6.6,"scd":{"b":7.0,"i":4.0,"r":6.5,"d":7.0,"t":5.0},"aip":1,"as":"水电解中气泡层会阻塞活性位点并增加传输和欧姆损耗。该研究开发表面应变NiMo阴极（s-NiMo），在0.5 M磷酸钾缓冲液（pH 7.0）中实现动力学解耦的氢气泡管理。NiMo与s-NiMo本征HER动力学几乎相同（H*吸附能相近），但在气泡调控运行条件下，s-NiMo在-20 mA/cm²下稳态过电位低63 mV。高速成像显示其氢气泡更小、脱离更快，实现稳定的近中性水电解。","kp":["电解体系[表面应变NiMo阴极析氢]: 0.5 M磷酸钾缓冲液近中性电解","功能特性[表面应变NiMo阴极]: 动学解耦氢气泡管理，降低气泡层造成的传质与欧姆损耗"]},{"t":"纳米级 In 2 O 3 诱导高负载固态阴极的快速动力学和稳定界面","b":"ABSTRACT Sulfide‐based all‐solid‐state lithium batteries (ASSLBs) with high‐loading cathodes are currently hindered by sluggish Li + /electron kinetics and poor interfacial compatibility. Conventional carbon additives, despite their high conductivity, often trigger detrimental side reactions with sulfide electrolytes. To mitigate these issues, we introduce a multifunctional nanoscale In 2 O 3 conductive agent, integrated via a facile one‐step ball milling process. This nano‐In 2 O 3 effectively mediates interactions between large Li 5.5 PS 4.5 Cl 1.5 (LPSC) and LiNi 0.8 Co 0.1 Mn 0.1 O 2 (NCM811) particles, enhancing mixing homogeneity and collision efficiency. The resulting composite cathode features a low‐tortuosity Li + transport network and establishes rapid “NCM‐nano In 2 O 3 ‐NCM” electronic pathways within particle gaps. Crucially, In 2 O 3 improves interfacial compatibility between the LPSC and conductive additives, suppressing interfacial degradation. Consequently, a high‐loading cathode (18.34 mg cm −2 ) demonstrates a specific capacity of 131 mAh g −1 at 3C and exhibits excellent cyclability, retaining 97.6% capacity after 500 cycles in NCM811||Li cells. This strategy highlights the potential of nanoscale metal oxide additives for achieving high‐energy‐density ASSLBs through optimized interfacial and transport kinetics.","d":"2026-09-03","u":"https://advanced.onlinelibrary.wiley.com/doi/10.1002/aenm.71543","c":"零碳产业/能量循环/能量存储/电化学储能/二次电池/锂电池","a":"Advanced Energy Materials","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"固态电池","sc":6.3,"scd":{"b":6.5,"i":4.5,"r":6.0,"d":7.0,"t":5.0},"aip":1,"as":"硫化物全固态锂电池高负载正极受限于缓慢的Li+/电子动力学和差的界面兼容性，且传统碳添加剂易与硫化物电解质发生有害副反应。该研究通过一步球磨引入多功能纳米In2O3导电剂，有效介导Li5.5PS4.5Cl1.5（LPSC）与大颗粒NCM811之间的相互作用，提升混合均匀性，构建低曲折度Li+传输网络及快速'NCM-纳米In2O3-NCM'电子通路，实现快速动力学和稳定界面。","kp":["导电添加剂[硫化物全固态锂电池高负载阴极]: 纳米级In2O3多功能导电剂，一步球磨工艺集成，改善Li+/电子动力学与界面兼容性并避免碳添加剂与硫化物电解质的副反应"]},{"t":"集成机器学习和高通量计算，合理设计光催化 2D-COF 的整体水分解","b":"ABSTRACT Two‐dimensional covalent organic frameworks (2D‐COFs) with tunable structures offer a promising platform for photocatalytic overall water splitting (OWS) under visible‐light. However, it is challenging to quickly find photocatalytic OWS materials from the massive amounts of 2D‐COFs and then achieve precise synthesis. In this work, we constructed 11 934 hcb‐type 2D‐COFs by assembling 28 building blocks and 9 linkages. The machine learning (ML) and high‐throughput computation (HTC) were integrated to predict feasible photocatalytic OWS hcb‐type 2D‐COFs. Through training 10 initial algorithms and optimizing the hyperparameters of top 4 algorithms in terms of performance, the ETR model for predicting the band‐edge levels with R 2 of 0.97 and 0.99 was developed, and the KNR and RFR models were built for predicting Δ G *H and Δ G *OH with R 2 of 0.99 and 0.83, respectively. 2581 2D‑COFs (21.63% of dataset) are screened to be potential structures for visible‑light‑driven water splitting. After applying the optimal ML models on all assembled 2D‐COFs, a list of high‐frequency building blocks and linkages is suggested as a set of suitable candidates for the first time. Then TBTZ_FBN0_Imine (TBTZ‐FBN0‐COF) was assembled and experimentally synthesized. Its OWS activity verified our ML‐HTC paradigm, which provides the researchers recommendation to construct photocatalytic OWS 2D‐COFs.","d":"2026-09-03","u":"https://advanced.onlinelibrary.wiley.com/doi/10.1002/aenm.71537","c":"通用技术/催化剂","a":"Advanced Energy Materials","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"COF光催化","sc":6.6,"scd":{"b":7.0,"i":3.5,"r":6.5,"d":7.5,"t":5.0},"as":"研究将机器学习与高通量计算相结合，从28个构筑单元和9种连接方式组装的11934个hcb型二维共价有机框架中预测可行的光催化整体分解水材料。通过训练10种初始算法并优化性能前4名的超参数，开发出预测带边能级的ETR模型（R²达0.97和0.99），以及KNR和RFR等模型，实现可见光下光催化2D-COF整体分解水材料的快速理性设计与精准合成。","kp":["数据库构建[光催化整体水分解2D-COF]: 由28个构筑单元和9种连接键组装11934个hcb型2D-COF","筛选方法[2D-COF光催化材料]: 机器学习与高通量计算集成理性设计"]},{"t":"三维拓扑自旋纹理与层相关符号变化调整晶格对称性之间的相互作用","b":"ABSTRACT Three‐dimensional (3D) topological spin textures host rich internal structures in thickness dimensions and enable emergent topological phenomena. However, whether their layer‐resolved textures and internal singularities fundamentally modify intralayer interactions lies beyond rigid‐tube interaction models and remains unexplored. Here we show that, in 3D hybrid skyrmion‐antiskyrmion strings, the layer‐dependent topology gives rise to interactions with a sign change across the film thickness, producing a switch between attraction and repulsion both among different layers within each texture and between neighboring 3D strings. This vertically asymmetric attractive‐repulsive interaction drives a tunable transition between square and triangular string lattices, in agreement with our experiment. Computational simulations identify quadrupolar Bloch points as internal topological junctions whose vertical migration mediates the intralayer competition between repulsive skyrmion segments near the surfaces and attractive antiskyrmion segments in the interior. We further show that the averaged topological charge quantifies the relative thickness fractions of the two competing topological segments and robustly captures the lattice phase boundary over a broad range of magnetic parameters. These findings highlight the importance of the surface‐bulk difference in topological materials and establish vertically asymmetric interactions as an intrinsic mechanism for topological phase control in 3D magnetic systems.","d":"2026-09-03","u":"https://advanced.onlinelibrary.wiley.com/doi/10.1002/adma.74896","c":"通用技术/材料工程/其它先进材料","a":"Advanced Materials","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"拓扑自旋纹理","sc":6.2,"scd":{"b":8.0,"i":2.0,"r":6.5,"d":6.0,"t":4.0},"as":"研究发现在三维混合斯格明子-反斯格明子弦中，层相关拓扑结构产生随薄膜厚度改变符号的相互作用，即同一纹理不同层间及相邻三维弦之间出现吸引与排斥的切换。这种垂直不对称的吸引-排斥相互作用驱动正方与三角弦晶格之间的可调谐转变，与实验观察相符，揭示了三维拓扑自旋纹理的层分辨结构和内部奇异性对层内相互作用的根本性影响，超越了刚性管相互作用模型。"},{"t":"阐明 O3 型 NaNi 1/3 Fe 1/3 Mn 1/3 O 2 高压降解的抑制：钠离子电池的电压切换策略","b":"ABSTRACT Elevating depth‐of‐charge (DoC) enhances the energy density of layered oxide cathodes for sodium‐ion batteries; however, such high‐DoC cycling inevitably triggers severe structural and interfacial degradation. In practice, battery management systems commonly adapt voltage‐derating strategies dynamically according to battery state of health, achieving a favorable trade‐off between energy density and cycle life. Nevertheless, a critical yet overlooked question remains: how high‐DoC‐induced damaged regions evolve when reverted to moderate‐DoC cycling. Here, using NaNi 1/3 Fe 1/3 Mn 1/3 O 2 (NFM111) as a prototype, a voltage‐switching strategy is employed to elucidate the dynamic and long‐term behavior of these damaged regions. During high‐DoC cycling (charging to 4.3 V), the rapid capacity fading is driven by pronounced formation of bulk defects and interfacial disordered spinel phases. However, upon switching these cells to moderate‐DoC cycling (charging to 4.0 V), these pre‐existing damaged regions become stabilized: their rapid propagation is suppressed, and they no longer accelerate degradation in surrounding intact regions. This enables degraded NFM111 to deliver capacity retention comparable to that of cells cycled solely under moderate‐DoC conditions. This work presents a dynamic and evolving picture of high‐DoC degradation and subsequent moderate‐DoC stabilization in NFM111 cathodes, providing mechanistic insights into voltage‐derating process and the lifetime prolongation of compromised cells.","d":"2026-09-03","u":"https://advanced.onlinelibrary.wiley.com/doi/10.1002/aenm.71535","c":"零碳产业/能量循环/能量存储/电化学储能/二次电池/钠电池","a":"Advanced Energy Materials","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"钠电降解抑制","sc":6.8,"scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"aip":1,"as":"高充电深度循环可提升钠离子电池层状氧化物正极能量密度，但会引发严重结构和界面退化。该研究以NaNi1/3Fe1/3Mn1/3O2（NFM111）为原型，采用电压切换策略阐明高充电深度（充电至4.3 V）造成的损伤区域在恢复至中等充电深度循环后的动态和长期演变行为，为电池管理系统在能量密度与循环寿命之间的权衡提供依据。","kp":["降解抑制策略[O3型NaNi1/3Fe1/3Mn1/3O2钠电阴极]: 电压切换策略抑制高充电深度循环引发的界面降解","核心问题[钠电层状氧化物阴极]: 高DoC循环引发严重结构与界面退化，需在能量密度与循环寿命间权衡"]},{"t":"仿生皮脂有机凝胶增强细胞膜流动性，实现无疤痕伤口愈合","b":"Wound scars impose a substantial clinical burden and aesthetic appearance, affecting millions of individuals globally. Herein, inspired by the physical protection and signal-regulating functions of human sebum, we developed a biomimetic sebum organogel for scarless wound healing. This organogel is composed of calcium phosphotungstate sub-nanowires (PWC) and squalene (Sql)—a natural component of human sebum. The PWC gelatinize Sql with high adhesion force for wound retention and Sql release. The released Sql integrates into the plasma membrane of fibroblasts, where it enhances lipid bilayer fluidity, relieves wound tension by facilitating membrane-associated cytoskeleton adaptation, and subsequently suppresses Yes-associated protein (YAP) activation. Through this mechanism, the biomimetic sebum organogel reduces scar formation and promotes regeneration of skin appendages. Our findings present an accessible strategy for scar prevention and also highlight the regulation of cellular membrane fluidity as a promising target for mitigating fibrotic conditions across a range of diseases.","d":"2026-09-03","u":"https://academic.oup.com/nsr/advance-article/doi/10.1093/nsr/nwag567/8781100?rss=1","c":"通用技术/材料工程/其它先进材料","a":"National Science Review Advance Access","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"仿生愈合凝胶","sc":6.7,"scd":{"b":8.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"as":"受人类皮脂物理保护和信号调节功能启发，研究人员开发了由磷酸钨酸钙亚纳米线（PWC）和角鲨烯（Sql，皮脂天然成分）组成的仿生皮脂有机凝胶用于无疤痕伤口愈合。PWC以高粘附力凝胶化角鲨烯，实现伤口滞留和角鲨烯缓释。释放的角鲨烯整合进成纤维细胞质膜，增强脂质双层流动性，通过促进膜相关细胞骨架适应缓解伤口张力，进而抑制YAP蛋白激活，实现疤痕-free愈合。","kp":["仿生皮脂有机凝胶[无疤痕伤口愈合]: 由磷钨酸钙亚纳米线(PWC)与角鲨烯组成，PWC使角鲨烯凝胶化并高黏附力于伤口滞留与缓释"]},{"t":"介孔萨伦聚合物纳米球的合成用于高效光催化从海水中提取铀","b":"Efficient uranium extraction from seawater is essential to the long-term sustainability of nuclear energy, yet the rational design of high-performance materials for this purpose remains a formidable challenge. Herein, we develop an ionization regulated self-assembly strategy to synthesize mesoporous Salen polymer nanospheres (mDSR) for photocatalytic uranium extraction. Partial ionization improves the aqueous solubility of otherwise insoluble Salen ligands and enhances their reactivity towards formaldehyde, while preserving sufficient precursor-micelle interactions for co-assembly, thereby directing the formation of ordered mesostructures. This strategy is facile, universal, and it can accommodate a series of structurally distinct Salen ligands, enabling the modular construction of mesoporous polymers with programmable molecular functions. The mDSR nanospheres feature a large pore size (6.2 nm), a high surface area (68 m2 g−1), and intrinsic photocatalytic activity. As a result, under simulated sunlight and without sacrificial agents, mDSR achieves a high uranium uptake capacity of 867 mg U g−1 from a 10 ppm U(VI) solution, outperforming most adsorbents. This protocol establishes a new paradigm for functional mesoporous polymers.","d":"2026-09-03","u":"https://academic.oup.com/nsr/advance-article/doi/10.1093/nsr/nwag569/8781101?rss=1","c":"零碳产业/物质循环/资源处理/资源回收","a":"National Science Review Advance Access","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"海水提铀材料","sc":6.7,"scd":{"b":8.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"aip":1,"as":"研究人员开发离子调控自组装策略合成介孔萨伦（Salen）聚合物纳米球（mDSR）用于光催化海水提铀。部分电离提高原本不溶性Salen配体的水溶性和与甲醛的反应性，同时保持足够的前体-胶束共组装相互作用，引导有序介观结构形成。该策略简便、通用，可容纳一系列结构不同的Salen配体，实现介孔材料的模块化构建，为高性能海水提铀材料设计提供新途径。","kp":["介孔萨伦聚合物纳米球[光催化海水提铀]: 通过离子调控自组装策略合成，部分离子化提升水溶性及对铀的反应性"]},{"t":"各国扩大研究计划，对不当行为实施严厉处罚","b":"India, Peru and Vietnam are rolling out policies that limit opportunities for scientists who fall foul of research-integrity guidelines.","d":"2026-09-03","u":"https://www.nature.com/articles/d41586-026-02517-1","c":"不相关","a":"Nature","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"埋内裤和接吻的新定义赢得 2026 年搞笑诺贝尔奖","b":"The awards highlight weird, funny and improbable research that also makes you think.","d":"2026-09-03","u":"https://www.nature.com/articles/d41586-026-02650-x","c":"不相关","a":"Nature","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"观点评论"},{"t":"神奇蘑菇化合物可以阻止小鼠化疗的严重副作用","b":"Study shows that psilocybin acts on nerves to prevent the painful condition called peripheral neuropathy.","d":"2026-09-03","u":"https://www.nature.com/articles/d41586-026-02744-6","c":"不相关","a":"Nature","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"体内设计的免疫疗法可缓解多发性硬化症","b":"Results from a small trial suggest a modified virus can instruct the immune system to wipe out disease-causing cells.","d":"2026-09-03","u":"https://www.nature.com/articles/d41586-026-02765-1","c":"不相关","a":"Nature","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"人类旁系同源补偿的中等流行率和进化原因","b":"Paralogous compensation drives genetic robustness; however, its in vivo","d":"2026-09-03","u":"https://academic.oup.com/nsr/advance-article/doi/10.1093/nsr/nwag565/8781095?rss=1","c":"不相关","a":"National Science Review Advance Access","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"中性粒细胞启发的可编程细菌用于细胞焦亡驱动的肿瘤根除","b":"Abstract Neutrophils represent a critical component of innate immunity, possessing intrinsic cytotoxic programs involving chemotaxis, degranulation, and lytic effector deployment. Here we report a neutrophil-inspired programmable bacteria (NPB) system developed via synthetic biology and molecular engineering. The nonpathogenic Escherichia coli MG1655 is programmed to execute a sequential four-stage program inspired by the “homing–bursting–lethality” logic of neutrophils with spatiotemporally controlled activation: (I) Preferential homing to hypoxic tumor regions; (II) Sonodynamic actuation of bacterial disruption and on-demand payload release via VHb-mediated ROS generation; (III) Tumor-associated gelatinase-responsive activation of Granzyme B zymogen (m-GzmB-T); and (IV) Pyroptosis-mediated enhancement of systemic antitumor immunity. The NPB system combined with focused ultrasound exhibited consistent antitumor efficacy across murine CT26, MC38, and EMT6 tumor models, while promoting systemic antitumor immune responses and durable immune memory. This work demonstrates the potential of engineering live bacteria with sequential physical and biochemical control mechanisms to execute bioinspired therapeutic cascades, providing a programmable and modular platform for precision cancer immunotherapy.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c16051/5413962/Neutrophil-Inspired-Programmable-Bacteria-for","c":"零碳产业/物质循环/有机物（碳循环）/有机工业/生物过程/合成生物学","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"可编程细菌","sc":6.9,"scd":{"b":8.5,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"aip":1,"as":"研究报道了一种受中性粒细胞启发的可编程细菌（NPB）系统，结合合成生物学与分子工程技术开发。以非致病性大肠杆菌MG1655为载体，模拟中性粒细胞的'归巢-爆破-杀伤'逻辑执行四阶段程序：优先归巢至缺氧肿瘤区域；通过VHb介导的ROS生成实现超声动力学的细菌裂解与按需载荷释放；响应肿瘤相关明胶酶激活Granzyme B酶原；最终经细胞焦亡介导肿瘤消融，实现时空可控的抗肿瘤治疗。","kp":["可编程细菌系统[中性粒细胞启发抗肿瘤]: 采用非致病性大肠杆菌MG1655，执行'归巢-爆裂-杀伤'四阶段程序并具备时空可控性"]},{"t":"拟南芥中胚胎来源的肽信号指导胚乳极性","b":"Angiosperm seed formation requires the coordinated development of the products of double fertilization—the embryo and the endosperm. The endosperm mediates efficient nutrient transfer from surrounding maternal tissues to the developing embryo. This function requires a polarized tissue organization, which manifests as early polar gene expression and polar cellularization dynamics. We show that the receptor kinase HAIKU2 (IKU2) acts in coordination with the transcription factor WRKY10/MINISEED3 (MINI3) to ensure robust endosperm polarity establishment through the activity of the homeodomain transcription factors WUSCHEL-RELATED HOMEOBOX 8 (WOX8) and WOX9. This process depends on egg cell fertilization and is mediated through the peptide PATHOGEN-INDUCED PEPTIDE–LIKE 7 (PIPL7), which acts as a potential IKU2 ligand. Our results reveal how a molecular paracrine dialog between the embryo and endosperm ensures optimal seed developmental coordination.","d":"2026-09-03","u":"https://www.science.org/doi/10.1126/science.aed6035","c":"不相关","a":"Science","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"温度依赖性伏安法揭示了 Pt 氨氧化反应过程中反应物种的电势依赖性形成及其对界面过剩电荷的影响","b":"Abstract The electrocatalytic ammonia oxidation reaction (AOR) has historically garnered significant interest, since ammonia could be used as a carbon-free fuel and convenient H2 carrier. Key challenges hindering its application are the high overpotentials and rapid catalyst poisoning, which remain poorly understood. Here, we study the overpotential-dependent formation of reaction species via temperature-dependent cyclic voltammetry and electrochemical Arrhenius analysis on polycrystalline Pt in conjunction with infrared spectroscopy. Further, we link the evolution of the kinetic parameters to the degree of polarization and excess charge via CO-displacement measurements. Strikingly, with increasing overpotential, we discover the parallel formation of a reaction species (not a direct intermediate) that modulates the electron chemical potential and, thus, the potential of zero charge. Due to this coupling, the parallel formation of this “poisoning” species appears to depolarize the surface with increasing overpotential. To recover the interfacial polarization, the overpotential needs to be increased further, before the activity can be restored and substantial Faradiac current can arise. What emerges is a new kinetic picture, where not only formation but also stabilization of interfacial excess charge are decisive for the catalyst activity. In general, the study demonstrates the utility of performing temperature-dependent cyclic voltammetry for revealing how transient changes in local chemicals modulate the overall inner-sphere kinetics.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c04573/5412824/Temperature-Dependent-Voltammetry-Reveals-the","c":"零碳产业/能量循环/能量存储/化学能/氢基能源","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"铂氨氧化","sc":5.9,"scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"as":"电催化氨氧化反应（AOR）因氨可作为无碳燃料和便捷氢载体而备受关注，但其高过电位和快速催化剂中毒机制尚不清楚。研究通过温度依赖循环伏安法、电化学Arrhenius分析结合红外光谱，研究多晶Pt上反应物种随过电位依赖的形成过程，并通过CO置换测量将动力学参数演化与极化程度和过剩电荷相关联。研究发现随过电位升高，一种反应物种平行形成，揭示了界面过剩电荷对反应的影响。","kp":["氨氧化反应机理[多晶Pt电极、温度依赖伏安法]: 揭示反应物种的电势依赖性形成及其对界面过剩电荷的影响"]},{"t":"大宗商品价格波动对欧洲经济体主权风险的影响：以俄乌冲突为例","b":"This paper investigates the impact of the Russo-Ukrainian conflict on the relationship between commodity price volatility and sovereign risk in European economies. Focusing on key agricultural commodities (wheat, rapeseed, and maize) and energy commodities (oil, gas, and coal) we examine the situation in European crop exporting and producing countries: France, Germany, Poland, Romania, Hungary, Bulgaria, Czechia, Italy, Portugal, Spain, the Netherlands, Denmark, Belgium, Finland, and the United Kingdom. Our results reveal that the spillovers originate primarily from the sovereign risk, while commodities are mainly shock receivers. Since the conflict began, the contribution of gas spillovers has increased, while that of wheat, maize, and coal has decreased. Moreover, the transmission of risks from Central Europe and Finland has also intensified. Overall, the findings suggest that geopolitical tensions drive the spillover transmission of commodity-related risk across the European Union and the UK.","d":"2026-09-03","u":"https://www.sciencedirect.com/science/article/pii/S0301421526005227?dgcid=rss_sd_all","c":"不相关","a":"ScienceDirect Publication: Energy Policy","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"羰基锰基过氧化物酶类纳米酶与葡萄糖氧化酶级联，结合卟啉-COFs 光疗和 CO 介导的免疫调节用于糖尿病伤口修复","b":"Abstract Diabetic wounds remain a global health challenge due to vascular insufficiency, bacterial infection, and persistent inflammation. Herein, we designed and prepared a triple-synergistic nanoenzyme platform with antibacterial, anti-inflammatory, and angiogenesis-promoting effects, which was formed by coloading a porphyrin covalent organic framework (Por-COF) with glucose oxidase (GOx) and manganese carbonyl (MnCO). Under near-infrared irradiation, Por-COFs produce a large number of reactive oxygen species (ROS) and localized hyperthermia. Simultaneously, GOx consumes the glucose in wounds to produce gluconic acid and H2O2, which trigger the decomposition of MnCO into immunomodulatory carbon monoxide (CO) and catalytically active Mn2+/3+ ions. The released Mn2+/3+ ions catalyze H2O2 to produce highly toxic •OH through peroxidase-like activity, enhancing bacterial elimination, while the produced CO improves M1-to-M2 macrophage polarization to resolve inflammation and suppresses heat-shock proteins to enhance PTT efficacy. This prepared nanoplatform (Por-COF@GOx/MnCO) achieved more than 99.99% antibacterial efficiency against Escherichia coli, Staphylococcus aureus, and methicillin-resistant Staphylococcus aureus and accelerated wound healing by promoting angiogenesis, ROS scavenging, and immunomodulation. The designed triple-synergistic nanoplatform—integrating glucose oxidase cascading MnCO-based peroxidase-like activity, phototherapy, and CO immunomodulation—shows great potential as a therapeutic strategy for diabetic wound repair.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c13461/5413694/Manganese-Carbonyl-Based-Peroxidase-like","c":"通用技术/材料工程/其它先进材料","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"纳米酶敷料","sc":5.7,"scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"as":"针对糖尿病伤口血管供血不足、细菌感染和持续炎症等挑战，研究设计了三重协同纳米酶平台：将葡萄糖氧化酶（GOx）和羰基锰（MnCO）共负载于卟啉共价有机框架。近红外照射下Por-COF产生活性氧和局部热疗；GOx消耗伤口葡萄糖生成葡萄糖酸和H2O2，触发MnCO分解释放免疫调节性一氧化碳和催化活性Mn2+/3+离子，Mn2+/3+催化H2O2分解，实现抗菌、抗炎和促血管生成的协同修复效果。","kp":["三重协同纳米酶平台[糖尿病伤口修复]: 卟啉COF共载葡萄糖氧化酶(GOx)与羰基锰，兼具抗菌、抗炎和促血管生成功能"]},{"t":"PEDOT 保形转印：将 PSS 图案转印到结构复杂的表面上","b":"Abstract Fabricating conductive circuits on complex curved surfaces remains a significant challenge for conformal electronics, particularly for soft and additively manufactured polymer substrates. We report a robust, conformal GOPS-assisted transfer-printing strategy for integrating inkjet-printed PEDOT:PSS patterns onto traditionally hard-to-print and non-planar surfaces. In this approach, conductive features are first defined on a planar polyimide donor substrate and subsequently transferred to the target substrate. The incorporation of (3-glycidyloxypropyl)trimethoxysilane (GOPS) into PEDOT:PSS facilitates strong covalent bonding, ensuring exceptional interfacial adhesion and structural integrity of transferred patterns. This transfer process is compatible with diverse non-planar substrates, including compliant PDMS, curved glass, and stereolithography (SLA)-printed resins. While direct printing on these substrates often suffers from poor wetting or non-planar surfaces, this transfer strategy yields continuous pathways that preserve the original morphology and electrical performance. Transferred films exhibited excellent stability, maintaining functionality through repetitive bending and aqueous immersion without delamination. As a demonstration, a functional organic electrochemical transistor (OECT) was fabricated on a curved 3D-printed substrate through a multi-step process, independently transferring electrodes and a semiconducting channel, and exhibited concentration-dependent responses to dopamine from 5 to 1000 nM. These results establish a versatile route for integrating printed conductive patterns and functional devices on complex polymer geometries.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c09969/5404453/Conformal-Transfer-Printing-of-PEDOT-PSS-Patterns","c":"通用技术/材料工程/其它先进材料","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"保形转印","sc":5.2,"scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"as":"在复杂曲面上制备导电电路是共形电子学的重大挑战。研究报道了一种GOPS辅助的保形转印策略，将喷墨打印的PEDOT:PSS图案集成到难以打印的非平面表面。导电图形先在平面聚酰亚胺供体基底上定义，再转印到目标基底。GOPS（3-缩水甘油醚氧丙基三甲氧基硅烷）的引入促进强共价键合，确保转印图案优异的界面粘附和结构完整性，兼容多种非平面基底。","kp":["转印工艺[PEDOT:PSS图案]: GOPS辅助保形转印，将喷墨打印的图案从平面聚酰亚胺供体基底转印至复杂曲面"]},{"t":"用于集成环境传感和修复应用的动态可驱动水凝胶","b":"Abstract Hydrogel-based adsorbents have emerged as versatile materials for environmental remediation and sensing owing to their tunable chemistries, hydrated networks, and compatibility with multifunctional nanomaterials. However, conventional static hydrogels remain constrained by diffusion-limited mass transport, slow adsorption kinetics, and limited integration of pollutant detection with remediation. This review highlights the emerging shift from passive adsorption toward dynamic and actuatable hydrogels as adaptive sense–respond–act material systems capable of accelerated pollutant capture, real-time monitoring, and autonomous regeneration. We first discuss static hydrogel design principles, including polymer composition, nanomaterial incorporation, and structural architectures that govern adsorption capacity, selectivity, kinetics, and reusability. We then examine dynamic hydrogel platforms, including intrinsically stimuli-responsive networks, extrinsically actuated composites, and shape-programmed architectures that actively enhance mass transport and interfacial exposure. Particular emphasis is placed on emerging systems that integrate sensing with decontamination, positioning actuatable hydrogels as adaptive environmental interfaces and soft robotic materials. A comparative discussion of static and dynamic systems evaluates their performance, practical limitations, and translational potential for water remediation, resource recovery, and integrated sensing technologies. Finally, challenges in scalability, stability, and system integration are critically assessed, and future directions are proposed toward autonomous, intelligent hydrogel platforms for next-generation environmental technologies.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c12257/5399042/Dynamic-Actuatable-Hydrogels-for-Integrated","c":"通用技术/材料工程/其它先进材料","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"观点评论","tp":"驱动水凝胶","sc":4.6,"scd":{"b":5.0,"i":3.0,"r":6.0,"d":5.0,"t":3.0},"as":"水凝胶吸附剂因其可调化学结构、水合网络和多功能纳米材料兼容性，成为环境修复和传感的多功能材料，但传统静态水凝胶受限于扩散控制的传质、缓慢的吸附动力学及检测与修复功能难以集成。本综述重点介绍从被动吸附向动态可驱动水凝胶的转变，作为'感知-响应-行动'自适应材料系统，实现加速污染物捕获、实时监测和自主再生，并讨论了静态水凝胶的聚合物组成、纳米材料复合和结构架构设计原则。","kp":["动态可驱动水凝胶[环境传感与修复]: 从被动吸附转向动态驱动，克服扩散限制的传质与慢吸附动力学"]},{"t":"用于多功能且材料高效的纳米颗粒薄膜的双相浸涂","b":"Abstract Colloidal quantum dot (cQD) thin films are central to solution-processed optoelectronics, yet scalable deposition methods that preserve device performance while improving material utilization remain limited. Here, we adapt a biphasic meniscus dip coating strategy that enables controlled deposition of cQD films while substantially reducing the volume of active nanocrystal solution required. In this approach, a thin cQD layer is supported by an immiscible underlayer, such that film formation occurs exclusively at the liquid–air interface of the active phase. Using this geometry, we fabricate PbS quantum dot photodetectors with responsivities up to ∼1000 mA/W at 1200 nm, comparable to conventional spin-coated devices. Relative to spin coating, the biphasic configuration reduces active solution consumption by up to 20-fold while maintaining film quality and reproducible device performance. A mass-volume cost analysis shows that the reduced active reservoir shifts the economic viability of dip coating into thickness and throughput regimes more relevant to practical device fabrication. We further extend the method to CsPbBr3 nanocrystals and curved substrates, highlighting its generality across material systems and geometries. Together, these results establish biphasic dip coating as a material-efficient and device-compatible manufacturing strategy for solution-processed optoelectronics.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c05752/5406638/Biphasic-Dip-Coating-for-Versatile-and-Material","c":"通用技术/材料工程/其它先进材料","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"量子点浸涂","sc":5.2,"scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"as":"胶体量子点薄膜是溶液法光电探测器件的核心，但兼顾器件性能与材料利用率的可规模沉积方法有限。研究采用双相弯月面浸涂策略，活性量子点薄层由不互溶的下层支撑，薄膜仅在活性相的液-气界面形成，大幅减少活性纳米晶溶液用量。利用该几何结构制备的PbS量子点光电探测器在1200 nm处响应度高达约1000 mA/W，与旋涂器件性能相当，同时相比旋涂显著降低活性材料消耗。","kp":["双相浸涂策略[胶体量子点薄膜]: 由互溶下层支撑薄cQD层，可控沉积并大幅减少纳米晶溶液用量"]},{"t":"通过掺镧 MnO2 阴极提高水系锌离子电池的可逆性和容量","b":"Abstract Manganese-based aqueous zinc-ion batteries (AZIBs) are regarded as promising candidates for large-scale energy storage owing to their safety, low cost, and environmental sustainability. Nevertheless, their practical deployment is limited by the poor electrical conductivity and structural instability of manganese-based cathodes, particularly the dissolution of active materials during cycling. In this study, lanthanum-doped manganese dioxide (La-doped MnO2) was synthesized through a mechanochemical reaction, followed by annealing to overcome these challenges. The incorporation of lanthanum markedly improves both the electrical conductivity and structural stability of MnO2. Consequently, the La-doped MnO2 cathode delivers enhanced electrochemical performance, achieving a high specific capacity of 288 mA·h·g–1 at 0.1 A·g–1 and excellent cycling stability, with 81% capacity retention at 0.4 A·g–1 after 500 cycles. These results reveal the potential of La-doped MnO2 as a high-performance cathode material for next-generation aqueous ZIBs.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c10899/5404234/Boosting-Reversibility-and-Capacity-in-Aqueous","c":"零碳产业/能量循环/能量存储/电化学储能/二次电池/其它电池体系","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"锌电池掺杂","sc":5.7,"scd":{"b":6.0,"i":4.0,"r":5.0,"d":7.0,"t":4.0},"as":"锰基水系锌离子电池因安全性、低成本和环保性被视为大规模储能的有力候选，但锰基正极导电性差、结构不稳定，尤其是循环中活性物质溶解，限制了实际应用。本研究通过机械化学反应合成掺镧二氧化锰（La掺杂MnO2）并退火处理，镧的掺入显著提升MnO2的导电性和结构稳定性，所得正极展现出更高的比容量和增强的电化学性能。","kp":["掺镧MnO2正极[水系锌离子电池]: 机械化学法合成，改善导电性、结构稳定性并抑制循环中活性材料溶解"]},{"t":"用于高倍率低温钠离子存储的富氧空位Na1.3Ti1.8Ni0.1Sb0.1(PO4)3@C阳极","b":"Abstract NASICON-type NaTi2(PO4)3 as an electrode material for sodium-ion batteries has attracted considerable attention due to its high structural stability and safety, yet its low intrinsic electronic conductivity limits high-rate and low-temperature performance. In this work, an oxygen-vacancy-rich Na1.3Ti1.8Ni0.1Sb0.1(PO4)3@C (N1.3T1.8N0.1S0.1P@C) nanopowder as a high-performance anode material is synthesized by a solvothermal method. The Ni2+/Sb5+ co-doping effectively modulates the local TiO6/PO4 lattice environment, introduces oxygen vacancies, and optimizes the lattice electronic structure, enhancing both electron and ion transport. A continuous carbon coating forms a stable conductive network, further improving kinetics and structural integrity. As a result, Na∥N1.3T1.8N0.1S0.1P@C half-cells retain 91% of their capacity after 5000 cycles at 20 C and maintain 86% capacity over 10,000 cycles at 10 C under 0 °C. The full cell paired with Na3V2(PO4)3 cathodes exhibits 87% capacity retention after 1000 cycles at 5 C and delivers excellent performance even at 50 C without pre-sodiation, highlighting their potential for low-temperature applications. This study provides a general doping-defect engineering strategy for NASICON-type anodes, enabling high-rate, low-temperature, and long-cycle performance for sodium-ion batteries.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c12328/5406711/Oxygen-Vacancy-Rich-Na1-3Ti1-8Ni0-1Sb0-1-PO4-3-C","c":"零碳产业/能量循环/能量存储/电化学储能/二次电池/钠电池","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"钠电阳极","sc":6.1,"scd":{"b":6.5,"i":4.0,"r":5.0,"d":8.0,"t":4.0},"as":"NASICON型NaTi2(PO4)3因高结构稳定性和安全性成为钠离子电池备受关注的电极材料，但其本征电子导电性低限制了高倍率和低温性能。研究通过溶剂热法合成富氧空位的Na1.3Ti1.8Ni0.1Sb0.1(PO4)3@C纳米粉体。Ni2+/Sb5+共掺杂有效调控TiO6/PO4局域晶格环境，引入氧空位并优化晶格电子结构，增强电子和离子传输；连续碳包覆构建稳定导电网络，进一步改善动力学和结构完整性，实现高倍率低温钠离子存储。","kp":["富氧空位NASICON阳极[钠离子电池]: Na1.3Ti1.8Ni0.1Sb0.1(PO4)3@C通过溶剂热法合成，Ni2+/Sb5+共掺杂调制局部结构实现高倍率低温储钠"]},{"t":"CVD 生长的大面积 MoS2/WS2 垂直异质结构中层间和混合激子的界面驱动演化","b":"Abstract Van der Waals heterostructures grown by chemical vapor deposition (CVD) offer a scalable platform for optoelectronic applications. However, understanding and accurately assigning their excitonic spectral features remain challenging. This is due to variable interfacial quality arising from interfacial disorder and interlayer coupling, as well as overlapping spectral signatures. Here, we synthesize continuous, large-area (up to 600 μm) MoS2/WS2 vertical heterostructures using two distinct single-step CVD processes. This approach enables a systematic comparison of excitonic behavior across varying interface qualities. Temperature-dependent photoluminescence, supported by ultra-low-frequency Raman spectroscopy, resolves the evolution of distinct interlayer exciton (ILE) spectral features. In heterobilayers, the ILE evolves from localized states in the presence of interfacial disorder to delocalized states stabilized by uniform interlayer coupling. Notably, we identify a hybrid exciton, arising from strong interlayer electronic hybridization, centered at ∼1.90 eV between the neutral A-excitons of MoS2 and WS2. Importantly, hybrid exciton formation correlates with a suppression of ILE radiative emission. By systematically disentangling disorder-trapped, delocalized, and hybrid excitonic regimes, this work provides clear experimental evidence of interface-driven excitonic transitions. These findings highlight the critical role of interfacial quality in governing excitonic behavior in scalable MoS2/WS2 heterostructures.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c10448/5405758/Interface-Driven-Evolution-of-Interlayer-and","c":"通用技术/材料工程/其它先进材料","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"异质结激子","sc":6.3,"scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":4.0},"as":"CVD生长的范德华异质结构为光电应用提供可扩展平台，但界面无序、层间耦合差异及光谱特征重叠使激子光谱指认困难。研究采用两种不同的单步CVD工艺合成连续大面积（达600 μm）MoS2/WS2垂直异质结构，实现不同界面质量下激子行为的系统比较。结合变温光致发光和超低频拉曼光谱，解析了不同层间激子光谱特征的演化，揭示了界面质量驱动的层间激子和混合激子演变规律。","kp":["异质结构面积[CVD生长MoS2/WS2垂直异质结]: 达600 μm","制备方法[大面积连续垂直异质结]: CVD化学气相沉积","激子光谱特征[MoS2/WS2异质结]: 层间激子与混合激子界面驱动演化"]},{"t":"三维打印水凝胶支架中的工程分层孔隙率增强了间充质干细胞对慢性糖尿病伤口的治疗","b":"Abstract Unhealing chronic diabetic wounds is a major clinical challenge, as it is rooted in the complex pathological microenvironment, including neuropathy, angiopathy, and chronic inflammation. Traditional treatment methods cannot fundamentally solve these problems. Inspired by outdoor rock climbing, this study developed a multifunctional bioactive hydrogel scaffold with hierarchical pore sizes (CSP hydrogel) to remodel the wound microenvironment and boost regenerative repair. Fabricated through 3D printing and photopolymerization from methacryloylated chitosan (CSMA) and methacryloylated silk fibroin (SiMA), the hydrogel has controlled properties: multi-scale porous structure (macropores ≥100 μm, mesopores 1–50 μm, micropores","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c16083/5405474/Engineered-Hierarchical-Porosity-in-Three","c":"通用技术/材料工程/其它先进材料","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"水凝胶支架","sc":5.0,"scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"as":"慢性糖尿病伤口因神经病变、血管病变和慢性炎症等复杂病理微环境成为重大临床挑战。受户外攀岩启发，研究开发了具有分层孔径的多功能生物活性水凝胶支架（CSP水凝胶），通过3D打印和光聚合由甲基丙烯酰化壳聚糖（CSMA）和甲基丙烯酰化丝素蛋白制成，形成宏孔（≥100 μm）、介孔（1-50 μm）和微孔的多尺度多孔结构，重塑伤口微环境并增强间充质干细胞的再生修复效果。","kp":["支架结构[3D打印水凝胶支架CSP]: 分级孔隙结构","功能[工程化分级孔隙水凝胶]: 重塑糖尿病伤口微环境、促进间充质干细胞再生修复","制备方式[多功能生物活性水凝胶支架]: 3D打印"]},{"t":"力学引导的双层分子半导体层层转移","b":"Abstract Layer-controlled organic thin films are essential components of organic electronic devices. Although layer-transfer methods are effective for device prototyping, managing crack formation during this process is challenging. In this study, we investigate the fracture mechanics of bilayer-type organic semiconductor (OSC) films as a model for developing a crack-suppressed transfer methodology. We find that crack formation is strongly dependent on film thickness and is suppressed when the film is reduced to a single molecular bilayer (SMB) thickness. The observed crack directionality in thick films is clearly correlated with the crystallographic orientation. These fracture behaviors can be qualitatively explained by combining a macroscopic elasticity model with calculations of intermolecular interaction energies. Based on this understanding, we successfully fabricate highly ordered multilayered artificial lattices through sequential SMB transfers. Furthermore, by expanding the π-electron core to tune intermolecular interactions, we achieve the direct patterning of OSC films, even on lyophobic substrates, providing a suitable interface for organic thin-film transistors (OTFTs). OTFTs incorporating crack-suppressed SMBs exhibit sharp on/off switching with a subthreshold swing of less than 150 mV dec–1 and a relatively high device mobility exceeding 5 cm2 V–1 s–1. These findings pave the way for molecular layer engineering for surface tailoring and organic device manufacturing.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c12628/5404035/Mechanics-Guided-Layer-by-Layer-Transfer-of","c":"通用技术/材料工程/其它先进材料","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"分子半导体转移","sc":5.0,"scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.5},"as":"层数可控的有机薄膜是有机电子器件的关键组件，层转移方法虽适用于器件原型制备，但过程中裂纹形成难以控制。研究以双层分子半导体薄膜为模型研究断裂力学，发现裂纹形成强烈依赖薄膜厚度，当薄膜减至单分子双层（SMB）厚度时裂纹被抑制。厚膜中观察到的裂纹方向性与晶取向明显相关，这些断裂行为可通过宏观弹性模型与分子间相互作用计算相结合定性解释，由此发展出抑制裂纹的转移方法。","kp":["裂纹控制[双层有机半导体薄膜转移]: 裂纹形成强烈依赖薄膜厚度，特定厚度下被抑制","研究方法[裂纹抑制转移工艺]: 双层有机半导体薄膜断裂力学分析"]},{"t":"用于神经形态计算中储层预处理的高性能微波合成石墨烯超级电容突触","b":"Abstract Reservoir computing bridges the gap between artificial intelligence and the physical environment. The realization of such systems depends on artificial synapses that emulate neurobiological plasticity in response to external stimuli. Functioning as reservoirs, these synapses convert the input signals into reservoir states, which are then retrieved by the readout layer. However, energy is merely dissipated during the operation of existing artificial synapses. Herein, we propose an energy-storage-involved reservoir architecture based on graphene-based supercapacitors. Reduced graphene oxide electrode, fabricated via metal-assisted microwave reduction, exhibits a mesoporous structure and low defect density. The supercapacitor delivers a specific capacitance of 352 F g–1 at a current density of 1 A g–1. Under current stimuli, the energy-storage device replicates biological synaptic functions through voltage responses. Next, the voltage responses can be used to mimic human perceptual learning, in which sensory systems are enhanced through experience. Moreover, integrated with a diffractive deep neural network in simulation, supercapacitor-based reservoir preprocessing can accurately identify static and dynamic handwritten images, outperforming an artificial neural network and an unprocessed diffractive deep neural network. These results pave the way for neuromorphic computing that integrates energy-storage-involved information processing, offering promising applications for energy-efficient artificial intelligence hardware.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c11501/5398904/High-Performance-Microwave-Synthesized-Graphene","c":"AI与智能科技/其它智能科技/脑机接口","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"突触超级电容","sc":5.1,"scd":{"b":6.5,"i":2.0,"r":5.0,"d":6.0,"t":4.5},"as":"储备层计算是连接人工智能与物理环境的桥梁，其实现依赖能响应外部刺激模拟神经生物可塑性的人工突触，但现有人工突触运行时仅耗散能量。研究提出基于石墨烯超级电容器的储能型储备层架构，通过金属辅助微波还原制备的还原氧化石墨烯电极具有介孔结构和低缺陷密度，超级电容器在特定电流密度下比电容达352 F g-1，为神经形态计算中的储备层预处理提供高性能突触器件。","kp":["储能功能[石墨烯超级电容人工突触]: 兼具能量存储与储备池计算预处理","制备方法[石墨烯超级电容突触]: 微波合成"]},{"t":"双光功能 Au/TiO2/NiO 纳米锥阵列为柔性 Zn−尿素−空气电池提供支持","b":"Abstract Photo-assisted Zn−air batteries provide an integrated route for solar energy conversion and storage, but their energy efficiency is still limited by sluggish bifunctional oxygen electrocatalysis at the air electrode. Herein, an Au nanoparticle-modified TiO2/NiO nanocone array air electrode (Au/n-TO/NiO) is developed for photo-assisted zinc−urea−air batteries. The nanocone TO architecture enhances broadband light harvesting, local electric-field intensity, and interfacial reactant enrichment, while the TO/NiO heterojunction promotes photogenerated charge separation. Under 365 nm irradiation, photogenerated holes preferentially migrate toward Ni-related active sites and accelerate urea oxidation, thereby reducing charging polarization. Meanwhile, Au nanoparticles serve as localized surface plasmon resonance centers, enabling efficient 808 nm photothermal conversion to regulate the oxygen reduction microenvironment during discharge. Benefiting from this functional partitioning of photoexcitation and photothermal regulation, the Au/n-TO/NiO-based battery exhibits a reduced charging plateau from 1.899 V in the dark to 1.585 V under combined illumination with urea, while the discharge plateau increases from 1.087 to 1.214 V. The apparent electrical round-trip efficiency consequently increases from 57.2% to 76.6% under the specified operating conditions. Furthermore, the flexible gel-state device achieves an apparent electrical round-trip efficiency of 81.5% under illumination with urea, demonstrating the potential of this strategy for flexible photo-assisted metal−air batteries.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c11867/5405521/Dual-Photo-Functional-Au-TiO2-NiO-Nanocone-Arrays","c":"零碳产业/能量循环/能量存储/电化学储能/二次电池/其它电池体系","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"锌尿素电池","sc":5.6,"scd":{"b":6.5,"i":2.5,"r":5.0,"d":6.5,"t":4.5},"as":"光辅助锌-空气电池为太阳能转换与存储提供一体化路径，但受空气电极缓慢的双功能氧电催化限制。研究开发了金纳米颗粒修饰TiO2/NiO纳米锥阵列空气电极用于光辅助锌-尿素-空气电池。纳米锥TiO2结构增强宽带光捕获、局域电场强度和界面反应物富集，TO/NiO异质结促进光生电荷分离。365 nm光照下，光生空穴优先迁移至Ni活性位点加速尿素氧化，降低充电极化，Au纳米颗粒则作为局域等离激元功能单元提升性能。","kp":["电极结构[光辅助Zn−尿素−空气电池]: Au纳米颗粒修饰TiO2/NiO纳米锥阵列（Au/n-TO/NiO）","纳米锥结构作用[TiO2纳米锥空气电极]: 增强宽谱光捕获、局域电场强度和界面反应物富集"]},{"t":"解耦传统有机太阳能电池中 PDINN/Ag 阴极界面的双热失效路径","b":"Abstract The conventional architecture of organic solar cells (OSCs) results in power conversion efficiency (PCE) but suffers from poor thermal stability, largely due to insufficiently understood interfacial degradation at the cathode side. Herein, we systematically investigate the thermal failure mechanisms of the widely used electron transport layer PDINN in conventional OSCs with a PM6:L8-BO/PDINN/Ag configuration. We identify a two-stage degradation pathway: In the initial heating phase, PDINN degradation induces n-type doping in the adjacent active layer near the cathode contact, reducing the short-circuit current density (JSC). Upon prolonged thermal stress, Ag− migrates through the PDINN interlayer, generating deep hole traps and shifting the cathode work function. The resulting energy level mismatch at the PM6:L8-BO/PDINN/Ag interface dramatically increases the electron extraction barrier, intensifying charge recombination and causing substantial losses in both open-circuit voltage (VOC) and fill factor (FF). Guided by this mechanistic understanding, we introduce a thermally evaporated C60/SnO2 bilayer between the active layer and PDINN as a diffusion-blocking interlayer. The modified devices retain 80% of their initial PCE (initial PCE: 16.96%) after continuous heating at 85 °C for 1000 h, in stark contrast to the rapid degradation of unmodified reference devices (T80","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c12107/5406367/Decoupling-the-Dual-Thermal-Failure-Pathways-at","c":"零碳产业/能量循环/能源测/发电技术/光伏","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"有机光伏失效","sc":4.8,"scd":{"b":5.5,"i":2.0,"r":5.0,"d":6.0,"t":4.5},"as":"传统结构有机太阳能电池（OSCs）虽然光电转换效率较高，但热稳定性差，主要归因于阴极界面降解机制不明。研究系统考察了PM6:L8-BO/PDINN/Ag结构中电子传输层PDINN的热失效机制，识别出两阶段降解路径：初期加热阶段，PDINN降解诱导阴极接触附近活性层的n型掺杂，降低短路电流密度；持续热应力下，Ag-穿透PDINN层迁移，产生深空穴陷阱并改变阴极功函数，导致器件性能进一步衰减。","kp":["器件结构[有机太阳能电池]: PM6:L8-BO/PDINN/Ag","热失效机制[PDINN/Ag阴极界面]: 两阶段降解路径"]},{"t":"简单两步法合成的 HgSe/PbS 核壳胶体量子点用于室温长波红外光电探测","b":"Abstract Mercury chalcogenides (HgX) colloidal quantum dots (CQDs), particularly mercury selenide (HgSe) CQDs, have emerged as a promising candidate for long-wave infrared (LWIR, 8–14 μm) photodetectors due to their exceptional bandgap tunability by solution processing. Nevertheless, the intrinsic limitations of bare HgSe CQDs—high surface defect density and oxidation susceptibility—severely compromise their optoelectronic performance. In this paper, a simple two-step method to grow high-quality HgSe/PbS core-shell CQDs in the LWIR region by synergistically optimizing the thickness of the PbS shell for surface passivation and the oxidation resistance of the HgSe cores is presented. Further, its applications in LWIR detection are explored using a simple metal–semiconductor–metal (MSM) based photodetector Au/(HgSe/PbS)/Au. As a result, a high responsivity of 42 mA/W with a high specific detectivity of 2.41 × 109 Jones under a 25 mW/cm2, 10 μm illumination is obtained from the LWIR photodetector Au/[HgSe(13 nm)/PbS(5 nm)](1 μm)/Au at room-temperature. Therefore, such a simple two-step method of core-shell engineering approach establishes a versatile platform for developing next-generation LWIR optoelectronics.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c13325/5411197/HgSe-PbS-Core-Shell-Colloidal-Quantum-Dots","c":"通用技术/检测和表征/先进科学仪器","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"红外量子点","sc":5.1,"scd":{"b":6.0,"i":2.0,"r":5.5,"d":6.0,"t":4.5},"as":"HgSe胶体量子点因可溶液加工的带隙可调性，成为长波红外（8-14 μm）光电探测的有力候选，但裸露HgSe量子点表面缺陷密度高、易氧化，严重影响光电性能。研究提出简单的两步法生长高质量HgSe/PbS核壳量子点，协同优化PbS壳层厚度以实现表面钝化和提升HgSe核的抗氧化性，并基于金属-半导体-金属（MSM）结构探索其在室温长波红外探测中的应用。","kp":["探测波段[HgSe/PbS核壳胶体量子点光电探测]: 室温长波红外（8–14 μm）","合成方法[HgSe/PbS核壳量子点]: 简单两步法","缺陷问题[裸HgSe胶体量子点]: 高表面缺陷密度和易氧化"]},{"t":"6LiInP2Se6 单晶：生长、缺陷结构、α 粒子光谱和直接转换 X 射线响应","b":"Abstract Room-temperature semiconductor crystals combining high resistivity, efficient charge transport, and a well-defined defect landscape are central to direct-conversion radiation detection. Here, we report the first demonstration of direct-conversion X-ray response in the layered selenophosphate 6LiInP2Se6 (LIPSe). Two crystal growth routes are advanced in parallel: chemical vapor transport (CVT), optimized for thin, high-purity flakes, and Bridgman–Stockbarger growth with iterative purification, scaled to centimeter-sized ingots. Both yield single crystals having clean (00l) surfaces and indistinguishable powder X-ray diffraction, Raman, and microscopic signatures, as well as matched band-edge alignment from photoelectron yield spectroscopy. Thermally stimulated current spectroscopy resolves trap levels spanning ∼0.13–0.68 eV, with estimated total trap densities of ∼1.2 × 1013 cm–3 (CVT) and ∼9.8 × 1014 cm–3 (Bridgman), while both crystals retain the high bulk resistivity required for room-temperature operation. Under 241Am irradiation, CVT detectors deliver well-resolved α-particle pulse-height spectra (∼22% energy resolution) with polarization-limited hole collection, while Bridgman detectors yield lower-bound single-carrier Hecht μτ products of ∼10–6–10–5 cm2 V–1 for both carriers. Under modulated X-ray exposure, sensitivities of ∼2.1 × 103 µC Gyair–1 cm–2 (CVT, ∼33 kV cm–1) and ∼6.5 × 103 µC Gyair–1 cm–2 (Bridgman, ∼22 kV cm–1) are achieved, where the larger Bridgman absorption volume offsets its trap-limited transport, identifying thickness scaling under continued defect control as the most direct path forward.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c13974/5404633/6LiInP2Se6-Single-Crystals-Growth-Defect-Structure","c":"通用技术/检测和表征/先进科学仪器","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"射线探测晶体","sc":6.0,"scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.5,"t":4.5},"as":"室温半导体晶体需兼具高电阻率、高效电荷传输和明确的缺陷结构，是直接转换辐射探测的核心。研究首次报道层状硒磷酸盐6LiInP2Se6的直接转换X射线响应，并行推进两种晶体生长路线：化学气相输运法（CVT）优化用于高纯薄片，以及带迭代纯化的Bridgman-Stockbarger法放大至厘米级晶锭。两种方法所得单晶具有洁净(00l)表面，粉末XRD、拉曼和显微表征一致，光电子产额谱显示带边对齐匹配，并通过热刺激电流谱表征缺陷结构及α粒子光谱响应。","kp":["晶体生长路线[6LiInP2Se6单晶]: 化学气相输运（CVT，优化薄型高纯度片晶）与Bridgman–Stockbarger法（迭代纯化）","功能[层状硒磷酸盐LIPSe]: 首次实现直接转换X射线响应","关键性能[室温半导体辐射探测晶体]: 高电阻率、高效电荷传输、明确缺陷结构"]},{"t":"通过弹性驱动的可逆动态键实现共变形导电复合薄膜","b":"Abstract The booming development of flexible electronics urgently calls for flexible conductive materials with outstanding mechanical strength, desirable elastic recovery, and reliable conductivity. Herein, a UV-curable polyacrylate conductive composite film (polyacrylate-AA-ChCl, PAAC) is rationally designed, featuring enhanced elastic recovery endowed by reversible hydrogen bonds. A polyacrylate (PA) film is first fabricated via UV-initiated polymerization using acrylate monomers and a vinyl-terminated polyurethane prepolymer as the cross-linker, exhibiting high transparency (>90%), solvent resistance (>72 h), favorable mechanical strength, and folding resistance. Subsequently, a polymerizable deep eutectic solvent (PDES)—specifically, acrylic acid/choline chloride (AA/ChCl)—was incorporated. This endows the composite with stable ionic conductivity while preserving its original mechanical properties. The resultant PAAC composite as a flexible strain sensor achieves excellent compatibility between components, outstanding mechanical durability (14.2 MPa and 735%), reliable conductivity (GF = 1.58) under deformation, and a low glass transition temperature (Tg = 4.5 °C). This work proposes a facile, scalable, and high-performance strategy for fabricating flexible conductive composites, which offers novel insights into the advancement of flexible electronics, wearable devices, and eco-friendly functional materials.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c13774/5406728/Co-deformable-Conductive-Composite-Films-via","c":"通用技术/材料工程/其它先进材料","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"导电复合薄膜","sc":4.4,"scd":{"b":5.0,"i":2.0,"r":4.5,"d":5.5,"t":4.0},"as":"研究设计了一种UV固化聚丙烯酸酯导电复合薄膜(PAAC)，通过可逆氢键赋予增强的弹性回复能力。首先以丙烯酸单体和乙烯基封端聚氨酯预聚体为交联剂，经UV引发聚合制备聚丙烯酸酯薄膜，具有高透明度(>90%)、耐溶剂性(>72小时)、良好的机械强度和耐折叠性。随后引入可聚合深共熔溶剂(丙烯酸/氯化胆碱，AA/ChCl)，实现可逆动态键驱动的共变形导电复合薄膜，满足柔性电子对机械强度、弹性回复和可靠导电性的需求。","kp":["弹性恢复机制[UV固化聚丙烯酸酯导电复合薄膜PAAC]: 可逆氢键弹性驱动","制备方法[聚丙烯酸酯导电复合膜]: UV引发聚合（丙烯酸酯单体+乙烯基封端，含ChCl）"]},{"t":"应变控制的界面传输控制顶部和边缘 n/p 型金属 TMD 结的接触电阻","b":"Abstract Contact resistance at two-dimensional (2D) metal-semiconductor interfaces remains a key bottleneck limiting transition-metal dichalcogenide (TMD) transistor performance. Strain engineering can reduce contact resistance, yet a predictive framework linking strain-induced electronic structure changes to interfacial carrier injection remains lacking. Here, we develop a multiscale framework combining first-principles calculations with analytical transport models to quantify strain-dependent contact resistance in metal-TMD junctions. We investigate n-type Au/MoS2 and p-type Pd/WSe2 contacts in top and edge geometries within experimentally accessible strain ranging from –1 to +1%. Tensile strain reduces n-type contact resistance by up to 46%/%ε, whereas compressive strain lowers p-type resistance by up to 34%/%ε. Edge contacts outperform top contacts by ∼2× due to direct interfacial hybridization. Under optimal strain and doping, room-temperature contact resistance reaches 0.32–0.74 and 0.51–0.84 kΩ·μm for Au/MoS2 and Pd/WSe2, respectively. These results quantitatively agree with experiments and benchmarks across alternative metal contacts, establishing a predictive framework for ultralow-resistance 2D-TMD transistors.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c10548/5404543/Strain-Controlled-Interfacial-Transport-Governs","c":"AI与智能科技/AI硬件层/半导体","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"TMD接触电阻","sc":5.0,"scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.5},"as":"研究构建了结合第一性原理计算与分析传输模型的多尺度框架，用于量化金属-TMD结中依赖应变的接触电阻。研究了n型Au/MoS2和p型Pd/WSe2接触在顶部和边缘几何构型下、实验可及应变范围(-1%至+1%)内的表现。结果表明，拉伸应变可使n型接触电阻每1%应变降低高达46%，而压缩应变则降低p型接触电阻。该框架建立了应变诱导电子结构变化与界面载流子注入之间的预测性联系，为降低二维半导体晶体管的接触电阻瓶颈提供了指导。","kp":["研究框架[应变依赖接触电阻预测]: 第一性原理计算结合解析传输模型的多尺度框架","技术作用[应变工程]: 可降低二维金属-半导体界面接触电阻"]},{"t":"用于防污和抗菌保护的紫外光固化生物基双疏涂料的仿生界面策略","b":"Abstract Surface protection is critical for advanced systems such as marine equipment and medical implants, where fouling and microbial deposition cause irreversible degradation. However, developing protective coatings that integrate multifunctionality (e.g., amphiphobicity and antifouling), environmental compatibility, and durability remains challenging. Inspired by beetle cuticle architecture, a bioinspired spontaneous interfacial reconfiguration strategy was introduced to construct a multifunctional coating that synergizes low-surface-energy enrichment with bioactive molecular interactions. Following this strategy, a bio-based amphiphobic and antibacterial coating (PCGBF@GT) was fabricated via a rapid, environmentally benign UV-curing process (within 5 min). Spontaneous migration of fluorinated segments in the castor oil-derived resin provides robust amphiphobicity and fouling resistance. Meanwhile, the incorporation of glycidyl methacrylate-modified tannic acid (GT) introduces hydrogen-bonding interactions and positive zeta potential, stabilizing the interface and enabling broad-spectrum antibacterial activity against Escherichia coli (99.92 ± 0.90%) and Staphylococcus aureus (99.83 ± 0.06%). This work demonstrates a sustainable, bioinspired pathway toward high-performance protective coatings for marine and biomedical applications.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c11815/5413388/A-Biomimetic-Interfacial-Strategy-of-UV-Curable","c":"通用技术/材料工程/其它先进材料","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"双疏防污涂层","sc":4.4,"scd":{"b":5.0,"i":2.0,"r":4.5,"d":5.5,"t":4.0},"as":"受甲虫表皮结构启发，研究提出仿生自发界面重构策略，构建兼具双疏性(疏水疏油)和防污抗菌功能的多功能涂层。采用快速(5分钟内)、环境友好的UV固化工艺制备了生物基双疏抗菌涂层(PCGBF@GT)，通过低表面能富集与生物活性分子相互作用的协同效应，实现含氟组分的自发迁移。该涂层面向海洋装备和医疗植入体等先进系统的表面保护，应对污损和微生物沉积造成的不可逆降解问题，同时兼顾多功能性、环境相容性和耐久性。","kp":["涂层策略[仿生界面自发重构]: 仿甲虫角质层结构构建多功能双疏涂料","功能特性[生物基UV固化涂料]: 双疏性、防污、抗菌、环境友好与耐久性集成"]},{"t":"从 p 型到 n 型：氯化诱导的轴向取代硅氧烷硅酞菁的电子和结构调制","b":"Abstract The development of air-stable n-type organic semiconductors remains a critical challenge for organic thin-film transistor (OTFT) technologies. Silicon phthalocyanines (SiPcs) bearing axial siloxane substituents have recently achieved record charge carrier mobilities but exhibit p-type behavior due to their relatively high-lying frontier orbital energies. Herein, we report the synthesis, characterization, and OTFT integration of two new chlorinated siloxane silicon phthalocyanines, (Si4O)2SiPcCl8 and (Si4O)2SiPcCl16, designed to lower the lowest unoccupied molecular orbital (LUMO) energy and enable n-type transport. Peripheral chlorination effectively reduces the LUMO levels to −3.8 and −4.0 eV, respectively, confirming the desired electronic modulation. Single-crystal X-ray diffraction reveals that chlorination disrupts the dense π-stacking observed in the parent unchlorinated derivative through two distinct mechanisms: increased intermolecular separation in (Si4O)2SiPcCl8 and severe core distortion in (Si4O)2SiPcCl16. These structural perturbations directly impact device performance: (Si4O)2SiPcCl8 OTFTs achieve average electron mobilities of 1.6 × 10−2 cm2 V−1 s−1, comparable to one of the best-performing alkyl-substituted SiPcs, while the highly distorted (Si4O)2SiPcCl16 derivative exhibits an order-of-magnitude lower mobility. Thin-film characterization by powder X-ray diffraction and atomic force microscopy, corroborated by density functional theory calculations, demonstrates that the (Si4O)2SiPcCl8 films adopt a favorable texture aligning the high-mobility crystallographic axis parallel to the substrate. This work establishes clear structure−property relationships for chlorinated SiPcs and provides a rational framework for the design of high-performance n-type phthalocyanine semiconductors.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c11582/5413692/From-p-Type-to-n-Type-Chlorination-Induced","c":"AI与智能科技/AI硬件层/半导体","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"硅酞菁半导体","sc":5.0,"scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.5},"as":"针对轴向硅氧烷取代硅酞菁因前线轨道能量较高而呈p型行为的问题，研究合成了两种新型氯化硅氧烷硅酞菁(Si4O)2SiPcCl8和(Si4O)2SiPcCl16，旨在降低LUMO能级实现n型传输。外围氯化有效将LUMO能级分别降至-3.8和-4.0 eV，证实了预期的电子调制效果。单晶X射线衍射表征了其结构，并将其集成到有机薄膜晶体管(OTFT)中，为开发空气稳定的n型有机半导体提供了新途径。","kp":["半导体材料[硅酞菁衍生物]: 轴向硅氧烷取代氯化硅酞菁实现p型向n型转变","性能水平[硅氧烷SiPcs]: 创纪录电荷迁移率但需解决空气稳定性n型行为"]},{"t":"用于双频带神经形态视觉和光学加密的掺镓 IGTO 纳米纤维晶体管的协同尺寸和缺陷工程","b":"Abstract Here, we report a synergistic strategy that integrates one-dimensional (1D) nanostructuring with precise Ga doping to fabricate high-performance indium-gallium-tin oxide (IGTO) nanofiber field-effect transistors (FETs). The optimized 5% Ga doping effectively suppresses oxygen vacancies (from 38.8 to 29.7%) via strong G–O bonds, enabling an excellent mobility of 2.79 cm2 V–1 s–1, a high on/off ratio of 4.15 × 107, a steep subthreshold swing of 0.50 V/dec, and remarkable bias-stress stability, thereby overcoming the classic mobility-stability trade-off in oxide semiconductors. Beyond the superior electrical characteristics, the IGTO nanofiber FETs exhibit a tunable dual-band photoresponse (340 nm UV and 430 nm visible), which successfully emulates essential synaptic behaviors, including excitatory postsynaptic currents, paired-pulse facilitation, and short-term to long-term memory transitions. Capitalizing on this wavelength-selective responsivity, we further demonstrate a proof-of-concept optical encryption-decryption system for MNIST digits, achieving a recognition accuracy of 95%. This work establishes a “dimensional control, precise doping, and defect engineering” paradigm, showcasing the great potential of IGTO nanofibers as a versatile platform for neuromorphic vision systems and secure optoelectronic applications.","d":"2026-09-03","u":"https://pubs.acs.org/aamick/article/doi/10.1021/acsami.6c12888/5403867/Synergistic-Dimensional-and-Defect-Engineering-in","c":"AI与智能科技/AI硬件层/半导体","a":"ACS Applied Materials & Interfaces: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"IGTO晶体管","sc":5.8,"scd":{"b":6.5,"i":3.0,"r":5.0,"d":8.0,"t":5.0},"as":"研究采用一维纳米结构与精确Ga掺杂相结合的协同策略，制备高性能铟镓锡氧化物(IGTO)纳米纤维场效应晶体管。优化的5% Ga掺杂通过强Ga-O键有效抑制氧空位(从38.8%降至29.7%)，实现2.79 cm2 V-1 s-1的优异迁移率、4.15×10^7的高开关比、0.50 V/dec的陡峭亚阈值摆幅及出色的偏置应力稳定性，克服了氧化物半导体中迁移率-稳定性的权衡。该器件展现可调双波段光响应(340 nm紫外和430 nm可见光)，成功模拟突触行为，可用于双频带神经形态视觉和光学加密。","kp":["Ga掺杂浓度[IGTO纳米纤维优化]: 5%","氧空位抑制[5% Ga掺杂]: 从38.8%降至29.7%","迁移率[IGTO纳米纤维FET]: 2.79 cm2 V–1 s–1","开关比[IGTO纳米纤维FET]: 4.15 × 107","亚阈值摆幅[IGTO纳米纤维FET]: 0.50 V/dec"]},{"t":"人类 Argonaute-2 对有机基 5′-磷酸盐的可编程识别","b":"Abstract To effectuate RNA interference (RNAi), Argonaute (AGO) proteins recognize and load RNA guide strands by their requisite 5′-phosphate (5′-P). However, the structural features that govern AGO2 tolerance for chemically modified 5′-P architectures remain poorly defined, despite their importance for small interfering RNA (siRNA) drug design. Moreover, degradative enzymes also recognize 5′-P, yet few stereoelectronic features are known to differentiate AGO2 recognition from competing degradation pathways. Here, we show that AGO2 accommodates a substantially broader range of 5′-P derivatives than previously recognized, and that select 5′-P mimics can exploit novel interactions with the protein to reinforce guide anchoring. Through systematic diversification of 35 organic substituents, we interrogated structural determinants of guide anchoring and enzymatic susceptibility. Our analysis identified previously uncharacterized 5′-P mimics, including methyl and phenylpropargyl 5′-phosphates (5′-PO-Me, 5′-PO-PhPrp), phenylpropargyl 5′-phosphorothioate (5′-PS-PhPrp), and 5′-mesylphosphoramidate (5′-MsPA), that preserve efficient AGO2 loading in cells while inhibiting phosphatase-mediated degradation. We further found that 5′-exonuclease susceptibility depends strongly on canonical 5′ phosphate chemistry rather than steric accessibility. Structural analysis of a 5′-PO-PhPrp guide:AGO2 complex shows that the phenylpropargyl substituent engages a π-stacking network within a cluster of aromatic side chains (Y529/F811/Y815), while extended 5′-P substituents are accommodated through rotation of the 5′-P and coordinated rearrangement of water molecules within the 5′-P binding pocket. Collectively, these findings reveal the structural basis for plasticity of guide anchoring in AGO2 and establish chemically programmable 5′-end interactions as a general strategy for modulating oligonucleotide stability and activity.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c03647/5413545/Programmable-Recognition-of-Organyl-5-Phosphates","c":"不相关","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"通过微调有机配体最大化 Dy 配合物的磁各向异性：对超过 25k 分子的系统多参考高通量探索","b":"Abstract The design of the coordination environment of magnetic ions is key to achieving properties such as large magnetic anisotropy and slow magnetic relaxation, but a systematic exploration of the relevant chemical space for these compounds is missing. Here, we automatically extract all entries of mononuclear Dy coordination complexes from crystallographic databases and use multireference ab initio methods to compute their magnetic anisotropy. In addition, we generate and simulate magnetic anisotropy for 25k new molecules with the general formula [Dy(H2O)5L2]n+ and pentagonal bipyramidal coordination geometry, a motif selected as very promising for its properties and for imparting synthetic realism to the generated compounds. While the screening of crystallography databases allows for correlations between electronic structure and coordination geometry to naturally emerge, molecules with crystal field splittings over 1600 cm–1 are identified by systematically exploring new organic ligands. This corresponds to a ∼100% increase of magnetic anisotropy over the reference compound with L = tBuPO(NHiPr)2, ∼40% over any known pentagonal bipyramidal Dy complex, and approaching the values of dysprosocenium. The systematic study presented in this work demonstrates the very large extent to which the fine-tuning of Dy’s second coordination sphere by organic ligands can affect magnetic anisotropy, and that automated high-throughput screening is capable of identifying chemical motifs statistically able to maximize such a property, therefore paving the way to the rational and automated design of magnetic molecules beyond established first coordination shell considerations.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c12194/5412228/Maximizing-the-Magnetic-Anisotropy-of-Dy-Complexes","c":"通用技术/材料工程/其它先进材料","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"镝磁配合物","sc":6.3,"scd":{"b":7.0,"i":2.0,"r":6.5,"d":7.0,"t":5.0},"as":"研究从晶体学数据库自动提取单核Dy配合物条目，采用多参考从头算方法计算其磁各向异性，并生成并模拟了2.5万个通式为[Dy(H2O)5L2]n+、具有五角双锥配位几何的新分子的磁各向异性，该构型因性质优异且具合成可行性被选为目标。通过微调有机配体最大化Dy配合物的磁各向异性，系统探索了相关化学空间，为设计具有大磁各向异性和慢磁弛豫性质的分子磁性材料提供了高通量筛选框架。","kp":["高通量筛选范围[Dy配合物磁性设计]: 超过25k单核Dy配合物","计算方法[磁各向异性预测]: 多参考从头算方法"]},{"t":"通过新颖的两步策略改进了热化学水分解中太阳能还原的反应器设计和性能","b":"","d":"2026-09-03","u":"https://www.sciencedirect.com/science/article/pii/S0306261926014352?dgcid=rss_sd_all","c":"零碳产业/能量循环/能源测/发电技术/光热","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"热化学分解","sc":4.6,"scd":{"b":5.5,"i":3.5,"r":5.0,"d":3.5,"t":5.0},"as":"采用新颖两步策略改进热化学水分解中太阳能还原反应的反应器设计与性能，提升制氢效率。","kp":["反应器策略[太阳能热化学水分解]: 新颖两步法改进太阳能还原反应器设计与性能"]},{"t":"温和条件下非活化 C(sp3)-H 键的钴催化、氨基喹啉定向官能化","b":"Abstract Second- and third-row transition metal catalysis in C(sp3)-H bond functionalization is well-established and is currently used in the synthesis of complex natural products, which can be considered the ultimate test of new synthetic methodologies. However, readily available and abundant first-row metals have been mostly employed in the functionalization of C(sp2)-H bonds. Their use in transformations of nonactivated (not benzylic or α to a heteroatom) C(sp3)-H bonds is rare and typically limited by the inability to functionalize secondary C–H bonds, high reaction temperatures, and the need to employ multiple equivalents of silver(I) oxidants. We report here a new approach to cobalt-catalyzed carbon–hydrogen bond functionalization by using a double-directing group strategy, enabling efficient activation of primary and secondary C(sp3)-H bonds under mild conditions to form β- or γ-lactams. Barium manganate is employed as an oxidant. Several Co(III) intermediates have been isolated and their reactivity is explored, supporting their involvement in the catalytic cycle. The reaction shows unusually high KIE kH/kD (>11) for C–H functionalization, allowing the use of deuterium as a blocking group, which enables amplified or switchable site selectivity. Mechanistic studies suggest a possible contribution of quantum tunneling in the C–H activation step.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c13556/5413961/Cobalt-Catalyzed-Aminoquinoline-Directed","c":"通用技术/催化剂","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"钴催化活化","sc":4.9,"scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.5,"t":5.0},"as":"研究报道了一种钴催化C-H键官能化的新方法，采用双定向基团策略，在温和条件下实现非活化C(sp3)-H键的官能化。第二、三行过渡金属催化C(sp3)-H官能化已成熟并用于复杂天然产物合成，而丰产的第一行金属此前主要用于C(sp2)-H键官能化，用于非活化C(sp3)-H键(非苄位、非杂原子α位)时罕见，且受限于无法官能化二级C-H键、反应温度高及需多当量银(I)氧化剂等问题。新策略克服了这些限制。","kp":["催化体系[非活化C(sp3)-H键官能化]: 钴催化、氨基喹啉定向、温和条件","技术特点[第一行过渡金属]: 实现非活化C(sp3)-H键罕见转化"]},{"t":"用于可编程寡核苷酸输送的序列定义的数字洗瓶刷聚合物","b":"Abstract Oligonucleotide therapeutics hold transformative potential, yet their clinical translation is hindered by delivery barriers, including rapid renal/hepatic clearance and poor organ specificity. Bottlebrush polymer conjugates have emerged as a promising vector to address these limitations, but conventional architectures with uniform backbones can only achieve an unmodifiable, rigid biodistribution profile. Here, we report a library of sequence-defined “digital” bottlebrush polymers, precisely engineered with controlled placements of chemical motifs that modify physicochemical properties─including lipids, cholesterol, and cationic groups─along a polyphosphodiester backbone. Systematic evaluation of the digital bottlebrush polymer library reveals distinct structure–property relationships and enables organ-biased systemic delivery to several traditionally difficult-to-reach tissues, including muscle and skin. In a mouse model of rheumatoid arthritis, a single dose of a spleen-homing polymer-conjugated antisense oligonucleotide targeting TNF-α significantly reduced arthritis severity and preserved animal body weight. These findings establish a versatile design framework for tailoring bottlebrush polymers to specific therapeutic applications.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c09537/5409520/Sequence-defined-Digital-Bottlebrush-Polymers-for","c":"通用技术/材料工程/其它先进材料","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"瓶刷聚合物","sc":5.7,"scd":{"b":7.0,"i":2.0,"r":5.5,"d":5.5,"t":5.0},"as":"研究报道了序列定义的“数字”瓶刷聚合物库，可精确控制脂质、胆固醇和阳离子基团等化学基元沿聚磷酸二酯骨架的排布，调控理化性质。系统评估揭示了明确的结构-性质关系。传统均一骨架瓶刷聚合物只能实现不可改变的刚性生物分布，而该数字瓶刷聚合物平台可编程修饰生物分布特征，用于解决寡核苷酸疗法面临的快速肾/肝清除和器官特异性差等递送障碍，实现可编程的寡核苷酸递送。"},{"t":"当铜下跌时：通过外层氢键超越欧文-威廉姆斯稳定性趋势","b":"Abstract The Irving–Williams series (Mn Zn) is a well-established thermodynamic stability trend among high-spin divalent first-row transition-metal complexes. However, complete isostructural Mn–Zn series are rare, and those that enable direct evaluation of a defined secondary coordination sphere are even rarer. As a result, whether outer-sphere noncovalent interactions can alter this periodic trend without changing the primary coordination environment has remained unresolved. Here, we present a complete isostructural octahedral series, (allLH)2MCl2 (M = Mn–Zn), supported by a flavin-derived bidentate ligand, allLH. An outer-sphere N–H···Cl hydrogen-bonding network provided by allLH locks all complexes into a single meridional isomer, enabling direct thermodynamic comparison across the row. In stark contrast to the classical Irving–Williams series, Cu(II) becomes the least stable species in the (allLH)2MCl2 series. Experimental and computational analyses show that this reversal arises from a finely balanced noncovalent constraint imposed by the rigid hydrogen-bonded scaffold. This scaffold retains the octahedral geometry of (allLH)2CuCl2 but only partially accommodates Jahn–Teller distortion, leaving the resulting stabilization insufficient to offset the accompanying attenuation of outer-sphere hydrogen-bond stabilization. This study demonstrates that a well-established metal-ion stability trend can be overcome by designing outer-sphere noncovalent interactions without altering the primary coordination environment.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c10430/5412502/When-Copper-Falls-Overriding-the-Irving-Williams","c":"通用技术/材料工程/其它先进材料","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"铜稳定性","sc":4.7,"scd":{"b":6.0,"i":1.5,"r":5.0,"d":5.0,"t":4.5},"as":"研究报道了完整的同构八面体系列(allLH)2MCl2(M=Mn至Zn)，由黄素衍生双齿配体allLH支持。该配体提供的外层N-H···Cl氢键网络将所有配合物锁定为单一经式异构体，实现跨第一过渡金属系的热力学直接比较。欧文-威廉姆斯系列(Mn<Fe<Co<Ni>Cu>Zn)是高自旋二价第一过渡金属配合物的成熟稳定性趋势，但完整同构系列罕见。该工作解决了外层非共价相互作用能否在不改变一级配位环境的情况下改变这一周期性趋势的问题。","kp":["研究发现[Mn-Zn等结构系列]: 外层氢键可改变欧文-威廉姆斯稳定性趋势而不改变初级配位环境"]},{"t":"用于表征电化学系统的原位拉曼光谱","b":"Shwetha Prakash explains how in situ Raman spectroscopy can be used to study electrochemical processes in real time.","d":"2026-09-03","u":"https://www.nature.com/articles/s44359-026-00214-w","c":"通用技术/检测和表征/先进科学仪器","a":"Nature Reviews Clean Technology","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"观点评论","tp":"原位拉曼","sc":3.3,"scd":{"b":3.5,"i":2.0,"r":4.5,"d":2.5,"t":4.0},"as":"本文作者Shwetha Prakash介绍了原位拉曼光谱如何用于实时研究电化学过程。原位拉曼光谱作为一种表征技术，能够在电化学系统运行过程中直接观测界面反应和中间物种，为电化学机理研究提供实时信息。本文属于技术解说类内容，正文仅提供了该要旨介绍，未包含具体实验数据或详细技术参数。","kp":["表征技术[电化学系统]: 原位拉曼光谱实时研究电化学过程"]},{"t":"卤化锡钙钛矿光伏电池的效率和耐用性","b":"Tin halide perovskites are lead-free alternatives to traditional perovskite photovoltaics but their efficiency is limited by easy defect formation and oxidation. This Review examines materials and device engineering strategies that could enable commercially viable photovoltaics from these materials.","d":"2026-09-03","u":"https://www.nature.com/articles/s44359-026-00210-0","c":"零碳产业/能量循环/能源测/发电技术/光伏","a":"Nature Reviews Clean Technology","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"锡钙钛矿","sc":5.4,"scd":{"b":5.5,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"as":"本综述探讨卤化锡钙钛矿光伏电池的效率与耐用性问题。卤化锡钙钛矿是传统铅基钙钛矿光伏材料的无铅替代方案，但其效率受易于形成缺陷和易氧化问题的限制。综述考察了可能使这类材料实现商业化可行光伏的材料与器件工程策略，涵盖缺陷调控、氧化抑制等方向，为实现高效稳定的无铅钙钛矿太阳能电池提供指导。","kp":["材料特性[卤化锡钙钛矿]: 无铅替代传统钙钛矿光伏","性能限制[卤化锡钙钛矿]: 易形成缺陷和氧化限制效率","改进方向[商用化]: 材料与器件工程协同提升效率和耐用性"]},{"t":"氧化异阿朴啡半夹心锇(II)衍生物：先天性肿瘤化学免疫疗法的催化触发剂","b":"Abstract Chemoimmunotherapy, particularly strategies that induce a tumor specific antitumor immune response, has emerged as a promising approach to improved cancer treatment. Nonetheless, only a limited number of drugs can successfully stimulate an antitumor immune response in vivo. Recent studies have highlighted the potential of metal-based anticancer agents in chemoimmunotherapy. Herein, we report a half-sandwich osmium(II) complex, Os-1, which acts as a catalyst for H2O2 generation through autocatalytic hydride transfer from coenzyme NADH to oxygen. Sustained H2O2 self-supply generation disrupts tumor redox homeostasis and induces DNA damage, leading to the activation of the cGAS-STING signaling pathway. Os-1 demonstrates potent cytotoxicity in vitro and elicits a robust antitumor immune response in vivo. Furthermore, Os-1 exhibits a synergistic antitumor growth effect when combined with a PD-1 inhibitor. To the best of our knowledge, this study is the first to describe the rational design of a small-molecule metal catalyst that provides for the in situ generation of H2O2 in cancer cells, thus overcoming the exogenous-additive bottleneck of oxidative therapy. This self-sufficient system not only promotes oxidative damage but also activates the cGAS-STING pathway, thereby integrating synergistically oxidative and immunotherapeutic actions.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c15572/5413289/Oxoisoaporphine-Half-Sandwich-Osmium-II-Derivative","c":"通用技术/催化剂","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"锇催化免疫","sc":5.1,"scd":{"b":6.5,"i":2.0,"r":5.0,"d":5.5,"t":5.0},"as":"研究报道了一种半夹心锇(II)配合物Os-1，可作为肿瘤化学免疫疗法的催化触发剂。Os-1通过自催化氢化物转移(从辅酶NADH到氧气)催化生成H2O2，持续的H2O2自我供给破坏肿瘤氧化还原稳态并诱导DNA损伤，进而激活cGAS-STING信号通路。Os-1在体外表现出强细胞毒性，并在体内引发强烈的抗肿瘤免疫反应，为金属基抗癌剂在化学免疫治疗中的应用提供了新范例。","kp":["催化机制[半夹心锇(II)配合物Os-1]: 催化H2O2生成触发肿瘤化学免疫治疗","药物类型[氧化异阿朴啡衍生物]: 先天性肿瘤化学免疫疗法催化触发剂"]},{"t":"绿色制氢系统设计优化与战略可靠性决策","b":"Green hydrogen (GH) is central to global decarbonisation strategies, yet its large-scale deployment remains constrained by high costs, limited operational experience, and the lack of integrated planning frameworks that jointly account for reliability, maintenance, and renewable resource variability across diverse grid connectivity and demand conditions. This study develops a novel reliability-based mixed-integer nonlinear programming (MINLP) framework that uses stochastic optimisation to simultaneously optimise technology selection, subsystem sizing, maintenance planning, and availability investment decisions for GH production systems, with green ammonia serving as the downstream energy carrier for long-distance transport. A case study in Eastern Canada identifies a wind-dominated configuration with supplemental solar and battery storage as the optimal solution, achieving a levelised cost of hydrogen (LCOH) of $4.44 kg −1 . Comparative geographic analyses reveal that wind-dominant regions achieve costs 18% to 41% lower than solar-dominant regions across best- to worst-case operating conditions, where lower solar capacity factors and stronger seasonal generation patterns necessitate substantially larger storage investments with limited production benefits. The framework also identifies two primary sources of renewable energy curtailment: the mismatch between installed renewable capacity and electrolyser absorption capability, and electrolyser downtime. Improving electrolyser availability reduces total curtailment by up to 48%, yet imposing stricter curtailment limits increases system costs without improving hydrogen production, with low-demand systems experiencing the greatest economic penalty due to higher incremental maintenance requirements. The findings demonstrate that maintenance strategies, curtailment management, grid interaction, and technology configuration must be jointly optimised under region-specific resource and demand conditions to achieve viable GH production. This study provides a practical framework to support these decisions during the design phase.","d":"2026-09-03","u":"https://www.sciencedirect.com/science/article/pii/S0306261926014157?dgcid=rss_sd_all","c":"零碳产业/能量循环/能量存储/化学能/氢基能源","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"绿氢系统优化","sc":5.5,"scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"as":"研究开发了一种基于可靠性的混合整数非线性规划(MINLP)框架，采用随机优化方法同时优化绿色制氢系统的技术选择、子系统规模、维护规划和可用性投资决策，以绿氨作为长距离运输的下游能源载体。该框架综合考量可靠性、维护和可再生能源资源可变性，适用于不同电网连接和需求条件。加拿大东部案例研究确定了以风电为主的配置方案，应对绿色氢气大规模部署面临的高成本和运行经验有限等制约。","kp":["规划框架[绿氢系统设计]: 基于可靠性的混合整数非线性规划(MINLP)与随机优化","主要挑战[绿氢大规模部署]: 高成本、运行经验有限、缺乏集成规划框架"]},{"t":"灵活性市场中的自适应谱聚类方法","b":"Market-based frameworks require aggregating flexible, granular resources into stable trading products to achieve efficient grid congestion management. The heterogeneous nature of demand-side flexibility, which entangles topological constraints with dynamic user preferences, renders static clustering ineffective. Frequent reclustering could capture these dynamics, but it introduces operational volatility and remains mathematically intractable for near-real-time operations. To resolve this stability-efficiency trade-off, this paper proposes a grid-aware State-Adaptive Hybrid Clustering (SAHC) method. Unlike rigid topological partitioning, SAHC employs a spectral approach to capture non-linear interactions between grid physics and economic behavior. The framework integrates a day-ahead initialization—Affinity Aggregation with Spectral Clustering (AASC)—with a dynamic intra-day engine that autonomously switches between a lightweight stateful update (Power Iteration Clustering) and a stateless re-estimation (Nyström approximation) based on spectral structural integrity. Simulations on the IEEE 33-bus system under an abrupt behavioral shift demonstrate that SAHC achieves lower computational latency with minor effects on economic efficiency. The approach attains flexibility costs comparable to high-fidelity benchmarks while reducing computation time by more than one order of magnitude relative to full spectral decomposition, enabling operation under strict real-time constraints. These results support SAHC as a scalable solution that ensures market continuity without the limitations of static approaches.","d":"2026-09-03","u":"https://www.sciencedirect.com/science/article/pii/S0306261926014236?dgcid=rss_sd_all","c":"通用技术/通信和运输/电网技术/配电和电力交易","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"灵活性聚类","sc":5.7,"scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":4.0},"as":"针对电力灵活性市场中需求侧资源异质性强、拓扑约束与动态用户偏好交织导致静态聚类失效的问题，研究提出电网感知的状态自适应混合聚类(SAHC)方法。与刚性拓扑分区不同，SAHC采用谱方法捕捉电网物理与经济行为间的非线性交互，并集成了日前初始化机制。该方法解决了频繁重聚类带来的运行波动和近实时运行下数学难解的问题，在稳定性与效率之间取得平衡，将细粒度灵活性资源聚合为稳定的交易产品以实现高效电网拥塞管理。","kp":["聚类方法[灵活性市场资源聚合]: 自适应谱聚类","技术问题[需求侧灵活性]: 静态聚类因拓扑约束与动态用户偏好耦合而失效"]},{"t":"通过双镍/能量转移催化未活化烯烃的定向基团自由基二碳官能化的模块化平台","b":"Abstract Multicomponent cross-coupling reactions of alkenes offer a powerful strategy for constructing three-dimensional, sp3 -rich molecular architectures, a key objective in modern medicinal chemistry. However, the regioselective dicarbofunctionalization of unactivated alkenes without the use of directing groups remains a significant challenge. Herein, we report a visible-light-induced, Ni-catalyzed platform that enables the radical 1,2-dicarbofunctionalization of unactivated alkenes using diverse alkyl radical precursors and aryl, vinyl, acyl, alkynyl, and alkyl coupling partners. Mechanistic studies support a catalytic cycle in which multiple electron donor–acceptor (EDA) complexes mediate radical generation, atom-transfer radical addition (ATRA), and cross-electrophile coupling (XEC) or bimolecular homolytic substitution (SH2) processes. Additionally, preferential formation of a complex between the Ni catalyst and the radical precursor suppresses undesired homocoupling of the electrophilic partner. Notably, delivery of gaseous radical precursors such as trifluoromethyl iodide (TFMI) from the robust metal–organic framework (MOF) Al(OH)fum (fum– = fumarate) or Al–fum offers advantages in terms of both operational safety and reaction efficiency, and the MOF further boosts the yields of reactions by decreasing the concentration of free amine (employed for radical generation) in solution. Collectively, this flexible, directing-group-free approach establishes a general platform for the rapid construction of structurally complex and pharmaceutically relevant molecules from readily available precursors.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c10952/5410885/Modular-Platform-for-Directing-Group-Free-Radical","c":"通用技术/催化剂","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"烯烃官能化","sc":7.1,"scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"aip":1,"as":"研究报道了可见光诱导、镍催化的平台技术，实现未活化烯烃的自由基1,2-二碳官能化，无需使用定向基团即可解决区域选择性难题。该平台采用多样的烷基自由基前体，以及芳基、乙烯基、酰基、炔基和烷基偶联 partner，构建富sp3的三维分子架构。机理研究支持一个由多个电子给体-受体(EDA)复合物介导的催化循环，涵盖自由基生成、原子转移自由基加成(ATRA)和交叉电亲体偶联(XEC)步骤，为药物化学的多组分交叉偶联提供了模块化平台。","kp":["催化平台[未活化烯烃1,2-二碳官能化]: 可见光诱导镍催化，无需导向基团的自由基1,2-二碳官能化"]},{"t":"SIG-LLM：用于时空多能源需求预测的语义知情门控法学硕士","b":"","d":"2026-09-03","u":"https://www.sciencedirect.com/science/article/pii/S0306261926014376?dgcid=rss_sd_all","c":"AI与智能科技/AI软件层/底座大模型/多模态模型","a":"ScienceDirect Publication: Applied Energy","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"能源需求预测","sc":4.4,"scd":{"b":6.0,"i":3.0,"r":5.0,"d":3.0,"t":4.0},"as":"提出SIG-LLM方法，利用语义知情门控大语言模型进行时空多能源需求预测，提升预测精度。","kp":["预测方法[时空多能源需求]: 语义知情门控大语言模型(SIG-LLM)"]},{"t":"均质铁卟啉作为分子 CO 穿梭使得 CO2 能够形成电化学多碳产物","b":"Abstract Homogeneous molecular catalysts for electrochemical CO2 reduction are generally limited to two-electron-reduced C1 products, primarily CO. Here we propose and demonstrate a fundamentally distinct role for molecular catalysts: as reversible CO shuttles that enhance the local CO activity at the electrical double layer. Using a water-soluble iron porphyrin as a CO shuttle, we observe the formation of isotopically verified C1–C4 hydrocarbons from CO2 in aqueous electrolyte. These products are not observed even in CO-saturated electrolyte in the absence of the iron porphyrin, indicating that the shuttle enhances local CO activity at the electrode surface beyond what bulk saturation can provide. Electrochemical and spectroscopic data support the formation of a stable FeII–CO species outside the compact layer, which releases CO upon further reduction at the electrode surface, consistent with an electrochemically gated shuttle mechanism. These findings suggest a potential design principle in which homogeneous catalysts function as molecular intermediate shuttles at the electrode surface and provide an alternative framework for interpreting beyond-CO products observed in heterogenized molecular catalyst systems.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c10179/5413457/Homogeneous-Iron-Porphyrin-as-a-Molecular-CO","c":"零碳产业/物质循环/有机物（碳循环）/有机工业/电化学过程/CO2RR","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"CO2还原催化","sc":7.9,"scd":{"b":9.0,"i":3.0,"r":8.0,"d":8.0,"t":6.0},"aip":1,"as":"研究提出分子催化剂的全新角色：作为可逆CO穿梭体增强双电层局部CO活度。使用水溶性铁卟啉作为CO穿梭体，在水系电解质中实现了从CO2生成经同位素验证的C1-C4烃类产物。即使在没有铁卟啉的CO饱和电解质中也不产生这些产物，表明穿梭体使电极表面局部CO活度超越了体相饱和所能达到的水平。电化学和光谱数据支持稳定FeII-CO物种的形成。该策略突破了均相分子催化剂电化学CO2还原通常仅限二电子还原C1产物(主要是CO)的限制。","kp":["CO穿梭催化剂[水相电化学CO2还原]: 水溶性铁卟啉作为可逆CO穿梭","产物[CO2电还原]: 同位素验证的C1–C4烃类（水系电解液）"]},{"t":"从脱氢到衍生化：分子催化下烷烃和烷基的官能化","b":"Abstract Alkane dehydrogenation has evolved from a fundamental organometallic challenge into a transformative technology for upgrading abundant hydrocarbon feedstocks and modifying complex molecules. This Perspective charts the evolution of modern alkane dehydrogenation, emphasizing the strategic divergence between well-established two-electron pathways and emerging radical-mediated reaction manifolds. For the dehydrogenation of structurally unbiased simple alkanes, research remains centered on noble-metal-based molecular catalysts, represented by pincer–transition-metal systems, where activity and regioselectivity are not only governed by catalysts’ first coordination sphere but also subtly affected by ligands’ scaffold. In contrast, for the dehydrogenation of hydrocarbons with electronically or thermodynamically differentiated C(sp3)–H bonds, a complementary paradigm has emerged in which reactivity is mainly dictated by the intrinsic properties of substrates. The interplay of bond dissociation energies (BDEs) and bond polarity can be harnessed by a diverse array of hydrogen atom transfer (HAT) reagents (or catalysts). We discuss how these two distinct mechanisms dictate the scope of both the dehydrogenation and dehydrogenation-triggered derivatization, which extends beyond small alkane functionalizations to controlled upcycling of macromolecular polyolefins. By analyzing the interplay between thermodynamic constraints, catalyst sustainability, and process integration, we outline a forward-looking roadmap for next-generation catalytic dehydrogenation systems.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c11696/5415244/From-Dehydrogenation-to-Derivatization","c":"通用技术/催化剂","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"观点评论","tp":"烷烃脱氢催化","sc":5.2,"scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"as":"本展望综述了分子催化下烷烃和烷基官能化的演变，从基础有机金属化学挑战发展为升级烃类原料和修饰复杂分子的变革性技术。文章强调成熟的双电子路径与新兴自由基介导反应模式的战略分歧：对结构无偏的简单烷烃脱氢，研究仍集中于贵金属基分子催化剂，以钳形-过渡金属体系为代表，其活性和区域选择性不仅受催化剂一级配位球控制，还受配体骨架的微妙影响；而对具有电子偏向性烃类的脱氢，自由基路径展现出不同优势。","kp":["反应路径[烷烃脱氢演化]: 双电子路径与新兴自由基介导路径的战略分化"]},{"t":"原子级精确的 Pt19：最大的全有机配体保护的铂纳米团簇，具有增强的稳定性和电催化活性","b":"Abstract Versatile organic ligands can notably enhance the stability and tunability of metal nanoclusters (NCs), and, consequently, all-organic ligand–protected metal nanoclusters have recently attracted widespread attention. Platinum (Pt) remains an indispensable metal in various fields, particularly in catalysis and cancer therapeutics. However, all-organic ligand–protected Pt nanoclusters are rarely reported due to substantial synthesis challenges, which have hindered progress in Pt nanocluster research and their practical applications. Herein, we report the successful synthesis of the largest all-organic ligand–protected Pt nanocluster to date, [Pt19(NapNC)27][PF6]2 (abbreviated as Pt19; NapNC: isocyanonaphthalene), achieved through the development of a ligand-exchange method. Single-crystal X-ray diffraction (SC-XRD) revealed a face-centered cubic (FCC), nonequivalent structure that has not been previously documented for all-organic ligand–protected Pt nanoclusters. Compared with its partially organic parent nanoclusters, this novel nanocluster exhibits considerably enhanced stability in both the ground and excited states. Furthermore, the Pt19 nanocluster demonstrates superior activity in the electrocatalytic methanol oxidation reaction (MOR) relative to its parent nanoclusters and commercial Pt/C. Based on its well-defined structure, we gained deep insights into the exceptional MOR activity of Pt19 and revealed, for the first time, the steric and electronic preferences of the active sites for electrocatalytic MOR.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c13812/5414623/Atomically-Precise-Pt19-The-Largest-All-Organic","c":"通用技术/催化剂","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"铂纳米团簇","sc":6.8,"scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"aip":1,"as":"研究通过开发配体交换方法，成功合成了迄今最大的全有机配体保护铂纳米团簇[Pt19(NapNC)27][PF6]2(简称Pt19；NapNC为异腈萘)。单晶表征确认其原子级精确结构。全有机配体可显著增强金属纳米团簇的稳定性和可调性，但由于合成难度大，全有机配体保护的铂纳米团簇此前极少报道。该Pt19纳米团簇展现出增强的稳定性和电催化活性，推动了铂纳米团簇研究及其实际应用，铂在催化和癌症治疗等领域不可或缺。","kp":["纳米团簇[全有机配体保护铂]: 原子级精确Pt19，最大全有机配体保护铂纳米团簇，稳定性与电催化活性增强"]},{"t":"在水介质中实现选择性和稳健的 CO2 电催化的主客体策略","b":"Abstract Heterogeneous materials incorporating molecular catalysts hold strong promise for efficient electrocatalytic CO2 reduction to value-added products. While activity and selectivity are traditionally tuned through ligand design, increasing attention is being paid to the second-coordination sphere, which modulates reactivity beyond the metal center. Inspired by enzymatic systems, this outer-sphere environment enhances catalysis through spatial confinement and noncovalent interactions. Here, we report a host–guest strategy to control CO2 reduction using the [bpyMn(CO)3MeCN]+ catalyst encapsulated in an anionic cage. When immobilized on an electrode surface, the assembly selectively produces CO. Mechanistic studies indicate that the cage promotes proton-coupled CO2 binding while preventing catalyst deactivation. This demonstrates that supramolecular second-sphere engineering is a powerful strategy for enhancing electrocatalytic performance and provides a basis for future developments in molecular electrocatalysts.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c10366/5412077/A-Host-Guest-Strategy-to-Achieve-Selective-and","c":"零碳产业/物质循环/有机物（碳循环）/有机工业/电化学过程/CO2RR","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"CO2电催化","sc":6.3,"scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"aip":1,"as":"研究受酶系统启发，提出主客体策略控制水介质中的CO2电催化还原：将[bpyMn(CO)3MeCN]+催化剂封装于阴离子笼中并固定在电极表面，该组装体选择性生成CO。机理研究表明，笼通过空间限域和非共价相互作用促进质子耦合的CO2结合，同时抑制副反应。该工作属于第二配位球工程，即通过金属中心之外的Outer-sphere环境调控催化反应活性与选择性，超越了传统配体设计调控活性和选择性的思路，实现了水中选择性和稳健的CO2电催化。","kp":["催化策略[水介质选择性CO2电催化]: 主客体（酶启发）策略，利用第二配位层空间限域与非共价相互作用"]},{"t":"双站点工程解锁了三角烯中的自旋调制和局部场控电荷切换","b":"Abstract Open-shell nanographenes, featuring highly tunable and correlated magnetic states, constitute a promising platform for engineering graphene nanomagnets towards molecular-scale spintronics and quantum information technologies. However, their magnetic states are largely dictated by topological constraints and strong electronic correlations, limiting independent control of spin and charge degrees of freedom. Here, we introduce a structural dual-site engineering strategy that integrates intrinsic spin modulation with adsorption- and field-controlled charge state tuning in a single magnetic nanographene, enabling a level of multifunctional control not previously demonstrated. We design and synthesize nitrogen, sulfur-co-engineered [3]triangulene (N,S-Tri), incorporating a central nitrogen dopant and an edge sulfur substitution with complementary functions. The central nitrogen modifies the occupation of the frontier π states and thereby tunes the molecular spin configuration, while the edge sulfur site weakly participates in the low-energy π-state and simultaneously acts as a tunable chemical anchor that regulates molecule–substrate coupling and charge transfer. Using low-temperature scanning probe microscopy, we directly visualize switching from neutral to cationic states, driven by adsorption-site variation on Au(111), or reversible switching by local electrostatic gating. This dual-functional design moves beyond static doping or interface charge transfer in graphene nanomagnets, enabling field-controlled dynamic modulation of spin and charge states, and opening new opportunities for device-oriented applications where molecule–electrode interactions and electrostatic field control play central roles.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c08110/5410151/Dual-Site-Engineering-Unlocks-Spin-Modulation-and","c":"AI与智能科技/其它智能科技/量子信息","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","sc":6.9,"scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"aip":1,"as":"研究提出双位点工程策略，在单一磁性纳米石墨烯中实现自旋调制与电荷态独立调控。设计合成了氮硫共工程化[3]三角烯（N,S-Tri），包含中心氮位点，将本征自旋调制与吸附及场控电荷态调谐相结合，实现此前未有的多功能控制水平。开壳层纳米石墨烯具有高度可调的关联磁性态，是构建面向分子级自旋电子学和量子信息技术的石墨烯纳米磁体的平台，但其磁性态通常受拓扑约束和强电子关联限制。该策略突破了自旋与电荷自由度难以独立控制的问题。","tp":"纳米石墨烯磁体"},{"t":"通过单颗粒电极解读铝硫电池中的电催化硫还原反应","b":"Abstract The kinetically sluggish sulfur reduction reaction (SRR) governs the performance of ultrahigh-capacity aluminum–sulfur batteries, while deciphering the SRR process is critical for rationally electrocatalyzing reaction kinetics to unlock their full energy output. To overcome this challenge, a single-particle electrochemical methodology has been developed to investigate the SRR process on a cobalt/nickel and nitrogen codoped graphene (CoNi-NG) electrocatalyst. The SRR process involves a major route of S8 → Al2S8 → Al2S4 → Al2S3 with a minor route of Al2S8 → Al2S6 → Al2S4, where Al2S4 conversion governs the overall SRR kinetics and Al2S4 contributes the most to the shuttle effect owing to its fastest generation and slowest consumption. The CoNi-NG raises the Co d-orbital energy level via Ni-to-Co electron transfer to accelerate cleavage of polysulfides, which doubles the exchange current density of rate-determining Al2S4 conversion. Consequently, the sulfur composite (S@CoNi-NG) electrode delivers a specific capacity of ∼1480 mAh gsulfur–1. Such a single-particle methodology for quantitatively deciphering electrocatalytic SRRs offers mechanistic guidance for rationally enhancing battery performance.","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c08648/5410310/Deciphering-Electrocatalytic-Sulfur-Reduction","c":"零碳产业/能量循环/能量存储/电化学储能/二次电池/其它电池体系","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"铝硫电池","sc":7.1,"scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"aip":1,"as":"研究开发了单颗粒电化学方法，在钴镍氮共掺杂石墨烯（CoNi-NG）电催化剂上研究铝硫电池中的硫还原反应（SRR）过程。发现SRR主要路径为S8→Al2S8→Al2S4→Al2S3，次要路径为Al2S8→Al2S6→Al2S4；其中Al2S4转化决定整体SRR动力学，且Al2S4因生成最快、消耗最慢而对穿梭效应贡献最大。CoNi-NG可提升Co d轨道能级。该研究对合理电催化改善动力学缓慢的SRR、释放铝硫电池超高容量的能量输出至关重要。","kp":["电催化剂[铝硫电池硫还原反应]: 钴镍氮共掺杂石墨烯","研究方法[SRR过程解读]: 单颗粒电极电化学方法"]},{"t":"超越漏斗式高通量筛选：专家指导的多元钙钛矿电催化剂探索的多尺度联系","b":"Abstract Navigating the vast compositional landscape of polynary oxide electrocatalysts is traditionally limited by funnel-style screening paradigms that treat high-fidelity data as binary gates rather than informative training signals. Here, we present an expert-guided multiscale framework for Pr–Sr–Co-Fe perovskites. By integrating atomic descriptors, experimental structural features, and mechanism-informed electronic features, this framework addresses these limitations within a descriptor-accessible polynary perovskite space. By implementing a “Nearest Grid Interpolation” strategy, the computational cost of high-fidelity density functional theory calculations is reduced by nearly 2 orders of magnitude within the search space. Two rounds of active learning surge the discovery efficiency of high-performance candidates (η@10 mA cm–2","d":"2026-09-03","u":"https://pubs.acs.org/jacsat/article/doi/10.1021/jacs.6c11110/5412407/Beyond-Funnel-Style-High-Throughput-Screening-An","c":"通用技术/催化剂","a":"Journal of the American Chemical Society: Latest Articles (ACS Publications)","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"钙钛矿筛选","sc":6.3,"scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"as":"针对多元氧化物电催化剂组分空间庞大、传统漏斗式筛选将高保真数据视为二元门槛的局限，研究提出专家指导的多尺度框架用于Pr-Sr-Co-Fe钙钛矿。该框架整合原子描述符、实验结构特征和机制导向的电子特征，并通过“最近网格插值”策略将搜索空间内高保真密度泛函理论计算成本降低近两个数量级。两轮主动学习显著提升了发现效率，在描述符可及的多元钙钛矿空间内高效探索电催化剂。","kp":["探索框架[多元钙钛矿电催化剂Pr–Sr–Co–Fe]: 专家指导的多尺度框架，整合原子描述符、实验结构特征与机制导向电子特征"]},{"t":"考古文物的粘性剩磁鉴定方法","b":"Museums and public collections often contain archaeological clay artifacts of unknown origin. Such artifacts, if proven to be authentic, may contribute significantly to our understanding of ancient societies. However, the authenticity of these artifacts is usually highly debated, resulting in their being disregarded in historical interpretations. Several laboratory methods have been developed in order to authenticate such objects but none have been proven infallible. Here we present a method for distinguishing between authentic and fake clay artifacts by considering the Viscous Remanent Magnetization (VRM) acquired by the artifacts. Clay objects tend to acquire a strong magnetic signal termed Thermal Remanent Magnetization (TRM) upon heating and cooling in kilns during their manufacturing process. After being removed from the orientation in which their TRM was acquired, these objects were exposed to an ambient geomagnetic field in a different direction. Over archaeological time scales, this results in the acquisition of a significant VRM. We propose a laboratory protocol for identifying this ancient VRM. We validated the protocol using micromagnetic modeling of single domain particles and by laboratory experiments carried out on 19 ancient and 26 modern objects, made from different types of clay and fired using different firing techniques. Both the experiments and the simulations indicate that the existence of a significant VRM component removed at temperatures higher than a cutoff temperature of\n                    \n                      \n                        \n                          112\n                          \n                            \n                            °\n                          \n                        \n                      \n                    \n                    C is indicative of ancient objects while its removal at lower temperatures is indicative of modern objects. We successfully applied this method to objects of debated authenticity.","d":"2026-09-03","u":"https://www.pnas.org/doi/abs/10.1073/pnas.2620397123?mi=eymic2&af=R&access=on&content=articlesChapters&publication=pnas&sortBy=Earliest&target=default","c":"不相关","a":"Proceedings of the National Academy of Sciences: Keyword search for query","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"利用生成式人工智能对非结构化数据进行因果推理","b":"We introduce GenAI-Powered Inference (GPI), a statistical framework for causal inference using unstructured data, including text and images. GPI leverages open-source pretrained Generative AI (GenAI) models—such as large language models and diffusion models—not only to generate unstructured data at scale but also to extract low-dimensional representations that are guaranteed to capture their underlying structure. Applying machine learning to these representations, GPI enables estimation of causal effects while quantifying estimation uncertainty. Unlike existing approaches to representation learning, GPI does not require fine-tuning of GenAI models, making it computationally efficient and broadly accessible. We illustrate the versatility of the GPI framework through three applications: 1) estimating the effects of Chinese social media censorship while adjusting for textual confounders, 2) isolating the impact of specific image features from that of other correlated features in the same image, and 3) assessing the persuasiveness of political rhetoric. An open-source software package is available for implementing GPI.","d":"2026-09-03","u":"https://www.pnas.org/doi/abs/10.1073/pnas.2530532123?mi=eymic2&af=R&access=on&content=articlesChapters&publication=pnas&sortBy=Earliest&target=default","c":"AI与智能科技/AI软件层/底座大模型/文本模型","a":"Proceedings of the National Academy of Sciences: Keyword search for query","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"生成式因果","sc":6.7,"scd":{"b":7.5,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"aip":1,"as":"研究引入生成式AI驱动推断（GPI）统计框架，利用文本和图像等非结构化数据进行因果推断。GPI利用开源预训练生成式AI模型（如大语言模型和扩散模型）大规模生成非结构化数据，并提取保证捕获其底层结构的低维表示，再对这些表示应用机器学习估计因果效应并量化不确定性。与现有表示学习方法不同，GPI无需微调生成式AI模型，计算高效且易于广泛使用，并通过多个应用展示其通用性。","kp":["[GPI框架]: 利用开源预训练生成式AI模型（大语言模型和扩散模型）生成非结构化数据并提取保证捕获其底层结构的低维表示","[GPI应用]: 基于表示的机器学习实现因果推断估计"]},{"t":"Hex-MASP 用于绘制全组织空间蛋白质组和单克隆抗体的脑内分布","b":"Whole-tissue level spatial proteomics provides critical insights into region-specific biological regulations but remains challenging. Previously, we introduced the micro-scaffold assisted spatial proteomics (MASP) concept for whole-tissue mapping. However, this prototype required substantial development in spatial resolution, practicality, and throughput for practical application. Here we present a next-generation MASP technique (\n                    hex-\n                    MASP) featuring i) a new design of hexagonal-micro-wells fabricated with optimized projection micro-stereolithography 3D-printing, achieving high spatial resolution, sampling robustness, and mechanical strength for reproducibly compartmentalizing even tough tissues; ii) enhanced throughput/effectiveness in sample preparation and LC–MS analysis with high quantitative quality. Applied to mouse brain,\n                    hex-\n                    MASP achieved in-depth, whole-tissue mapping for &gt;6,000 proteins in mouse brains, with high spatial accuracy and excellent data quality. The substantially improved resolution revealed critical regional details across the entire brain, that were not previously captured, enabling precise depiction of protein distribution heterogeneity. This technique enabled the identification of many unreported regionally enriched proteins across brain structures. We further applied\n                    hex-\n                    MASP to investigate the intrabrain distribution of intracerebroventricularly dosed antibody therapeutics and related proteins, which enabled whole-tissue mapping of protein drugs revealed insights into antibody brain penetration and distribution.\n                    Hex\n                    -MASP represents a robust, scalable platform for whole-tissue spatial proteomics.","d":"2026-09-03","u":"https://www.pnas.org/doi/abs/10.1073/pnas.2532946123?mi=eymic2&af=R&access=on&content=articlesChapters&publication=pnas&sortBy=Earliest&target=default","c":"不相关","a":"Proceedings of the National Academy of Sciences: Keyword search for query","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"关于金属伴侣 UreE 和 UreG 如何相互作用以将有毒金属传递给脲酶的结构见解","b":"Maturation of urease, a virulence factor for\n                    Helicobacter pylori\n                    infection, requires the delivery of nickel ions to the metalloenzyme. To avoid cytotoxicity, Ni(II) ions are transferred within protein complexes of metallochaperones to ensure that the toxic metal does not escape into the cytoplasm. In the urease maturation pathway, metallochaperone UreG receives its Ni(II) ions by forming a 2:2 complex with another metallochaperone UreE. Using C-terminal truncation variants of UreE [UreE(1-158) and UreE(1-148)], we determined the crystal structures of the UreE\n                    2\n                    G\n                    2\n                    complex bound with Ni(II) ions and GMPPNP, a nonhydrolyzable GTP analogue. UreE–UreG interactions are asymmetric, with the UreG dimer interacting mainly with the proximal UreE (closest to UreG). GTP binding induces conformational changes in the residues Asp37-Asp43 and the CPH motif (Cys66-Pro67-His68) of distal UreG that enable its anchorage to the UreE\n                    2\n                    G\n                    2\n                    complex. His68 of distal UreG moves toward and chelates a Ni(II) ion at the UreE binding site. Formation of the UreE\n                    2\n                    G\n                    2\n                    complex juxtaposes the Ni(II) binding sites of UreE and UreG. Supported by in vitro binding analyses, structural comparison suggests that nickel transfer from UreE to UreG induces conformational changes that weaken UreE–UreG interactions, thereby providing a mechanism for the dissociation of Ni(II)-bound UreG from the UreE\n                    2\n                    G\n                    2\n                    complex. Our work presents a paradigm on how GTP and Ni(II) binding allosterically regulate the formation of a metallochaperone complex to facilitate nickel transfer.","d":"2026-09-03","u":"https://www.pnas.org/doi/abs/10.1073/pnas.2535662123?mi=eymic2&af=R&access=on&content=articlesChapters&publication=pnas&sortBy=Earliest&target=default","c":"不相关","a":"Proceedings of the National Academy of Sciences: Keyword search for query","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"极端气候事件导致土壤抗生素抗性基因发生一致且可预测的变化","b":"Antimicrobial resistance (AMR) is a growing One Health challenge, and as climate warming intensifies extreme events, it remains unclear how these disturbances affect soil antibiotic resistance genes (ARGs). Here we analyzed the data from a controlled experiment using soils from 30 grassland sites across ten European countries, which simulated drought, flooding, freeze–thaw, and heatwaves to explore ARG dynamics. Overall, ARGs exhibited relatively small but highly consistent shifts across treatments. Heatwaves caused the strongest reductions in ARG abundance and in their linkages with mobile genetic elements (MGEs), a pattern that may reflect a hypothesized metabolic–genetic trade–off, in which microbial investment may shift from core metabolism toward stress signaling and structural maintenance. ARG dynamics during and after disturbance were governed by distinct soil physicochemical properties, with temperature and nutrient status determining acute responses, whereas soil moisture and seasonal variability in temperature and precipitation shaped longer–term legacy effects. Cross–validated random–forest models showed positive predictive performance for Bray–Curtis–based compositional responses within the environmental range represented by the 30 grassland sites. Our findings enhance the understanding of how soil ARGs respond to extreme climatic events and provide a step toward predicting extreme–event impacts on soil resistomes with relevance to One Health.","d":"2026-09-03","u":"https://www.pnas.org/doi/abs/10.1073/pnas.2612278123?mi=eymic2&af=R&access=on&content=articlesChapters&publication=pnas&sortBy=Earliest&target=default","c":"不相关","a":"Proceedings of the National Academy of Sciences: Keyword search for query","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"鱼通过偏航介导的横向迁移在水动力迷宫中航行","b":"In aquatic environments, gradients in flow velocity and turbulence define a constantly shifting landscape that sets the physical constraints on propulsion and energy expenditure in fish. Successfully navigating these complex flows depends on the ability to sense and respond to subtle hydrodynamic cues in an energy-efficient manner. Revealing these mechanisms is central to understanding how fish identify and exploit favorable flow conditions. To this end, we designed a hydrodynamic maze with spatially varying mean flow and turbulence, creating a controlled heterogeneous flow landscape for understanding fish movement strategies. We found that fish escape energetically unfavorable regions by yawing their bodies relative to the flow. These yawed orientations appear to facilitate lateral migration through lift forces and may improve sensitivity to local flow variations. Notably, fish maintain body orientations near, but below, predicted stall conditions to exploit lift without a significant increase in drag. These findings provide insight into how fish navigate heterogeneous hydrodynamic environments, with potential relevance for both natural and engineered flow systems.","d":"2026-09-03","u":"https://www.pnas.org/doi/abs/10.1073/pnas.2613565123?mi=eymic2&af=R&access=on&content=articlesChapters&publication=pnas&sortBy=Earliest&target=default","c":"不相关","a":"Proceedings of the National Academy of Sciences: Keyword search for query","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"Lenacapavir 与未成熟 Gag 结合诱导巨大病毒粒子并引起蛋白酶依赖性病毒释放抑制","b":"Lenacapavir (LEN), a potent capsid inhibitor, suppresses reverse transcription and nuclear import by disrupting capsid core formation in HIV type 1 (HIV-1). However, its effects on late-stage viral assembly remain unclear. Although p24 ELISA suggested that LEN substantially inhibited HIV-1, both RT-dPCR and Vpr-HiBiT assays indicated that suppression of viral release required relatively high LEN concentrations. This discrepancy was attributed to LEN-induced reduction in p24 solubility, leading to an overestimation of its inhibitory effect on viral release. In addition, excessive intracellular Gag processing by the viral protease was observed in the presence of LEN, which contributed to impaired viral release. Furthermore, LEN induced numerous abnormal, discrete clusters of Gag at the plasma membrane. Using mass photometry, which was applied to analyze HIV-1 particle sizes, and transmission electron microscopy, we identified heterogeneous LEN-induced viral-like particles (LENiVLPs; diameter &gt;200 nm) containing both Gag and Env proteins. Although LENiVLPs retained membrane fusion capability, they were noninfectious owing to postentry defects that prevented viral replication. Thus, LEN binds to the precursor Gag and promotes aberrant particle formation, offering insights that could guide the development of next-generation LEN-based therapeutics targeting the late stages of the viral life cycle.","d":"2026-09-03","u":"https://www.pnas.org/doi/abs/10.1073/pnas.2609634123?mi=eymic2&af=R&access=on&content=articlesChapters&publication=pnas&sortBy=Earliest&target=default","c":"不相关","a":"Proceedings of the National Academy of Sciences: Keyword search for query","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文"},{"t":"小狄拉克分量对固体中锕系元素原子核价电子密度的影响","b":"Author(s): A. V. Nikolaev, U. N. Kurelchuk, and E. V. TkalyaAn enhanced Full-Potential Linear Augmented Plane Wave (FLAPW) method is introduced which incorporates the small Dirac components of valence states—specifically the 6p1/2 semicore states—in actinide solids such as Ac, Th, ThO2, and UO2. By accounting for these small components, it is demonstrated that the valence electron density at the nucleus increases by a factor of 2.4 to 4.3, correcting standard approximations in computational physics that omit significant valence electron density near the atomic nucleus. These refined relativistic Dirac calculations offer improved theoretical precision for nuclear phenomena such as internal conversion, Mossbauer spectroscopy, and electron bridge effects, providing foundational electronic structure insights relevant to technologies like 229Th-based solid-state nuclear clocks.[Phys. Rev. C 114, 034601] Published Thu Sep 03, 2026","d":"2026-09-03","u":"http://link.aps.org/doi/10.1103/fmc6-8f4q","c":"通用技术/材料工程/其它先进材料","a":"Recent Articles in Phys. Rev. C","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"研究论文","tp":"锕系计算","sc":6.0,"scd":{"b":6.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"as":"研究引入增强的全势线性缀加平面波（FLAPW）方法，在锕系固体（Ac、Th、ThO2和UO2）中纳入价态的小狄拉克分量，特别是6p1/2半芯态。计算表明，考虑这些小分量后，原子核处的价电子密度增加2.4至4.3倍，纠正了忽略原子核附近显著价电子密度的标准计算近似。改进的相对论狄拉克计算为内转换、穆斯堡尔谱和电子桥效应等核现象提供更高理论精度和电子结构基础。","kp":["价电子密度增益[锕系固体含小狄拉克分量]: 增大2.4至4.3倍","计算方法[锕系固体Ac/Th/ThO2/UO2]: 纳入6p1/2半芯态小狄拉克分量的增强全势线性缀加平面波(FLAPW)方法"]},{"t":"用于古埃及艺术品的身体部位追溯到令人惊讶的来源","b":"Coffin decorations and wall paintings were made with tissue from a broad range of organisms.","d":"2026-09-04","u":"https://www.nature.com/articles/d41586-026-02739-3","c":"不相关","a":"Nature","i":"l","source":"news_with_abstract_2026-09-04.csv","sr":"literature/news_with_abstract_2026-09-04.csv","tg":"观点评论"}]);